  "landing.heroH": "可验证的结构分析。",
  "landing.heroP": "在您自己的机器上求解 2D 和 3D 框架与桁架，并已与其他七个有限元程序进行对比验证。仍在开发中的 AI 助手已可在同一模型和求解器上工作，使用您自己的 Claude 或 OpenAI 密钥。",
  "landing.heroCtaPrimary": "打开编辑器",
  "landing.heroBlogLink": "阅读我们的博客",
  "landing.heroMetaA": "适用于任何现代浏览器",
  "landing.heroMetaB": "开源",
  "landing.heroMetaC": "阿根廷制造 · FIUBA · Ergodic Group",
  "landing.fitH": "Stabileo 的定位",
  "landing.fitDeskH": "商业桌面软件",
  "landing.fitDeskP": "SAP2000、ETABS、Robot、STAAD.Pro：闭源，需安装，支持的设计规范多得多，并有数十年的使用历史。Stabileo 是开源的，在浏览器中运行。",
  "landing.fitScriptH": "开源求解器",
  "landing.fitScriptP": "OpenSees、Code_Aster、CalculiX：开源且功能强大，通过脚本或输入文件运行。Stabileo 是可视化的，我们将其求解器与这三者都做了对比。",
  "landing.fitClassH": "教学软件",
  "landing.fitClassP": "Ftool 常见于土木工程课程，用于分析平面框架。Stabileo 增加了 3D，并展示每个结果背后的计算过程。",
  "landing.modBasic": "基础",
  "landing.modProCalc": "PRO · 分析",
  "landing.modProDesign": "PRO · 规范设计",
  "landing.modEdu": "教学",
  "landing.modAi": "Stabileo AI",
  "landing.priceFree": "免费",
  "landing.ebBasic": "基础",
  "landing.badgeFreeAlways": "永久免费",
  "landing.basicH": "土木工程的开源“口袋计算器”。",
  "landing.basicP": "建模、加载、求解并查看 2D 和 3D 结果。它展示计算过程，而不只是答案。",
  "landing.basicPt1": "实时计算：拖动节点或修改荷载时，结果随之更新。",
  "landing.basicPt2": "分步展示刚度法：单元矩阵、组装、求解。",
  "landing.basicPt3": "几何组成分析（2D）可找出机构，包括计数公式遗漏的情形。",
  "landing.basicPt4": "截面分析会说明适用哪种扭转理论：实心截面、Bredt 或圣维南（Saint-Venant）。",
  "landing.basicPt5": "2D 和 3D 的 P-Δ、屈曲和模态分析；2D 的塑性倒塌和影响线。",
  "landing.ebProCalc": "PRO · 分析",
  "landing.proCalcH": "有限元与复杂模型。",
  "landing.proCalcP": "楼板和墙、分阶段施工、非线性和动力分析，使用与基础模式相同的经过验证的求解器。",
  "landing.ebProDesign": "PRO · 设计",
  "landing.proDesignH": "规范验算与构件设计。",
  "landing.proDesignP": "验算并设计杆件：混凝土按 CIRSOC 201，钢结构按 CIRSOC 301（试验性），荷载和组合按 CIRSOC 101–104。按 AISC 360、EN 1993-1-1、AISI S100、ACI 318 和 EN 1992-1-1 进行的试验性验算涵盖有限的截面。",
  "landing.metaDescription": "免费开源，在浏览器中使用：2D 和 3D 框架与桁架。CIRSOC 201 设计以及试验性的 AISC、ACI 和 Eurocode 验算为付费功能，高校免费。AI 助手开发中。",
  "landing.metaTitle": "Stabileo — 开源结构工程软件，AI 开发中",
  "landing.proDesignCirsocLink": "目前按 CIRSOC 验算的内容",
  "landing.proDesignRoadmapLink": "3D 设计的后续工作",
  "landing.ebVerif": "验证",
  "landing.verifH": "我们如何检验结果，以及检验的边界。",
  "landing.verifP": "求解器在您的电脑上运行。我们将其与七个有限元程序和已发表的结果进行对比，并检验物理不变量。在可行时，它还会计算一份证书：数值误差的界限，其核心数学已用 Lean 证明，适用于线性、模态和塑性倒塌分析。该界限只涵盖对已组装方程组的求解，不说明模型本身是否正确。可能已影响实际使用结果的缺陷会以公告形式发布。",
  "landing.verifHow": "我们如何检验，以及其局限",
