  "pro.examples.groupValidation": "验证模型",
  "ex.validation-01": "验证 01 · 带楼板的钢结构建筑",
  "ex.validation-01.desc": "一座三层建筑，钢框架，混凝土楼板和核心筒墙按壳划分网格，与一个已发表的结构一一对应建模，保留其编号和网格。梁位于楼板中面之下，以杆端偏移表示，楼板压力为面荷载。",
  "ex.validation-01.purpose": "验证 / 楼板 / 偏移",
  "pro.tagValidation": "验证",
  "ex.validation-06": "验证 06 · 水平力作用下的平面框架",
  "ex.validation-06.desc": "一个两跨五层的钢框架，与一个已发表的结构一一对应建模，保留其编号。原程序生成的地震力以节点荷载施加，仅用于生成质量的两个重力工况保留为普通工况。截面由其属性给出，计入剪切变形。",
  "ex.validation-06.purpose": "验证 / 地震 / 剪切",
  "ex.validation-02": "验证 02 · 带桁架的轻型仓库",
  "ex.validation-02.desc": "一座钢结构仓库，有三榀坡屋面桁架门式刚架、檩条和支撑桁架，与一个已发表的结构一一对应建模，保留其编号。刚性结点、整体坐标系下的杆端偏移以及檩条的滚转角均与原结构一致；弦杆荷载给定在整体和局部坐标轴中。",
  "ex.validation-02.purpose": "验证 / 桁架 / 偏移",
  "ex.validation-03": "验证 03 · 带墙的库房",
  "ex.validation-03.desc": "一座库房，两道混凝土墙按四边形壳划分网格，承托由四榀桁架和五根纵向槽钢组成的钢屋盖，与一个已发表的结构一一对应建模，保留其编号和网格。角钢按其主轴给定，每根杆件的滚转角与原结构一致。",
  "ex.validation-03.purpose": "验证 / 墙 / 壳",
  "ex.validation-04": "验证 04 · 带吊车梁的工业机库",
  "ex.validation-04.desc": "一座钢结构机库，有屋架、门、附属建筑、吊车梁和管廊，与一个已发表的结构一一对应建模，保留其编号：2482 根杆件，其中许多杆端为铰接，共 22 个荷载工况。各工况按线性求解，每个组合按其设计荷载进行 P-Delta 分析；原程序也对各工况进行 P-Delta 分析。原程序的杆件规范验算未复现。没有稳定二阶平衡的组合会被列出，但不公布其内力。",
  "ex.validation-04.purpose": "验证 / P-Delta / 杆端释放",
  "ex.validation-05": "验证 05 · 拉索塔",
  "ex.validation-05.desc": "一座三角形格构塔，高 57.6 m，由十八根拉索锚固于三个锚点，与一个已发表的结构一一对应建模，保留其编号。拉索只受拉，组合是各工况之和，各自有其激活集，与原结构一致；风荷载也作用于拉索。",
  "ex.validation-05.purpose": "验证 / 仅受拉 / 叠加",
  "ex.validation-07": "验证 07 · 带楼面荷载的建筑",
  "ex.validation-07.desc": "一座平面不规则的四层混凝土建筑，与一个已发表的结构一一对应建模，保留其编号。楼面荷载已按梯形分配到梁上，并在每根杆件处截断；每层为一个刚性隔板，自重计入恒荷载工况。",
  "ex.validation-07.purpose": "验证 / 楼面 / 隔板",
