  "project.export": "导出",
  "project.importHelp": "用电子表格中的模型替换当前模型。请先下载模板：其中包含各工作表、各列以及每种的示例，这是该导入功能唯一能读取的 Excel 格式。要打开 .ded 文件，请使用上方的“打开”。DXF 和 IFC 在 PRO 中提供。",
  "project.exportViewHelp": "用于报告或考试的图：结构、其内力图以及平衡的隔离体，在白底上清晰绘制。格式在对话框中选择：SVG（矢量，可编辑或打印）、PNG 或 JPG。也可直接复制并粘贴到文档中。",
  "project.exportReportHelp": "您提交的文档。您可以选择其内容：模型数据、荷载、几何组成分析、平衡的隔离体，以及各项结果（表格、图或两者兼有）；格式可选 PDF、Word 或 HTML。",
  "project.exportResultsHelp": "可继续使用的数据。Excel：包含模型和结果（汇总、杆件、节点、支座反力、材料、截面、壳和组合）的工作簿，每项一个工作表。CSV：仅结果表。若模型尚未求解，导出时会先求解。两者都无法在此重新导入：导入请使用模板，且模板使用不同的工作表。",
  "project.importSpreadsheet": "从电子表格",
