  "flex.scope": "全部八个工作表都逐单元格进行了对比，包括其双筋部分、六个特征点以及它们绘制的相互作用曲线序列。已说明的差异：圆形截面的结果比工作簿轻约 0.6 %；双向受弯曲面的截面在象限中部最多大 0.6 %，工作簿在此处对受压区做了离散化；在圆形工作表上，工作簿在轴力上限处的弯矩是其自身网格间隙上的一条直弦，使曲线高估 4.4 %，而我们取的是曲线上的点；并且，当钢筋不再能放入一层时，此处将钢筋分层叠放，d 取至钢筋组的形心，所需钢筋比工作簿多，而工作簿始终假定为单层。2005 年之后的版本，结果可能不同，且未与工作簿对比验证。",
  "flex.attribution": "CIRSOC 201-2005 条文。为我们自行实现，并对照 INTI-CIRSOC 的 CIRSOC_FLEX 工作簿（D. A. Ortega）的结果进行了测试。",
