  "axes.diagOn": "简支梁跨中作用集中荷载 P。正剪力及使梁底受拉的弯矩沿局部 +z 方向绘制，在水平梁上即向上绘制。",
  "axes.diagNote": "局部坐标系的手性不改变此图。正值朝局部轴正向绘制时，另一平面内的内力图（Vy、Mz）会翻转。全局坐标轴不影响此图。",
  "axes.diagAria": "跨中受集中荷载的简支梁及其剪力图和弯矩图",
  "config.axisConventionHelp": "右手：局部 Y 轴遵循右手法则（ex × ey = ez）。左手：将 Y 轴反向。它决定局部坐标轴的显示方式、杆件内力图绘制在杆件的哪一侧，以及在局部坐标轴中输入的荷载方向（qY、Py 沿您所见的 Y 轴）。分析始终采用右手系：同一物理模型得到相同的结果。",
