  "whatsNew.title": "Stabileo {version}：您的结果可能已发生变化",
  "whatsNew.body": "此版本修正了验算中的错误结果（3D CIRSOC 201 柱、EN 1992 受弯、CIRSOC 301 受压、受压最小的钢筋混凝土柱）、荷载生成器、屈曲、谐响应和时程分析、3D 到 2D 的剖切以及壳的组合应力，每项均附有安全公告（SA-2026-025 至 047）。部分模型现在会被拒绝求解或给出标记，而不是静默求解；2D 塑性倒塌在修复上线前仍保持拒绝求解。请重新运行您的项目，并在依赖早先结果之前复核其验算。",
