  "tooltip.toolSelect.title": "选择（V）",
  "tooltip.toolSelect.desc": "含 5 种子模式：节点、杆件、支座、荷载和应力。可在浮动工具栏中切换。",
  "tooltip.toolNode.title": "创建节点（N）",
  "tooltip.toolNode.desc": "在画布上点击以放置连接点。节点是杆件相连和施加荷载的位置。",
  "tooltip.toolElement.title": "创建杆件（E）",
  "tooltip.toolElement.desc": "先点击起始节点，再点击终止节点，即可在两者之间创建杆件。框架 = 刚接，桁架 = 铰接。",
  "tooltip.toolSupport.title": "创建支座（S）",
  "tooltip.toolSupport.desc": "点击节点以放置支座。支座类型决定被约束的位移。",
  "tooltip.toolLoad.title": "施加荷载（L）",
  "tooltip.toolLoad.desc": "点击节点（集中荷载）或杆件（分布荷载）以施加力。负值 = 向下。",
  "tooltip.toolInfluence.title": "影响线（I）",
  "tooltip.toolInfluence.desc": "显示单位荷载在结构上移动时，某个反力或内力如何变化。",
  "tooltip.toolPan.title": "平移视图（H）",
  "tooltip.toolPan.desc": "拖动以移动视图。也可使用鼠标中键或 Ctrl+拖动。",
  "tooltip.solve.title": "求解",
  "tooltip.solve.desc": "使用直接刚度法（DSM）求解结构。需要节点、杆件、支座和荷载。",
  "tooltip.selfweight.title": "自重",
  "tooltip.selfweight.desc": "根据材料密度和截面面积自动添加重力分布荷载。",
  "tooltip.diagNone.title": "无内力图",
  "tooltip.diagNone.desc": "隐藏所有结果图，仅显示结构。",
  "tooltip.diagDeformed.title": "变形图",
  "tooltip.diagDeformed.desc": "显示放大的变形图。便于检验结构性能是否合理。",
  "tooltip.diagMoment.title": "弯矩（M）",
  "tooltip.diagMoment.desc": "各杆件的弯矩图。按惯例绘制在受拉侧。",
  "tooltip.diagShear.title": "剪力（V）",
  "tooltip.diagShear.desc": "沿各杆件的剪力图。突变表示有集中荷载。",
  "tooltip.diagAxial.title": "轴力（N）",
  "tooltip.diagAxial.desc": "轴力图。正值 = 受拉（杆件伸长），负值 = 受压。",
  "tooltip.diagAxialColor.title": "轴力着色（N±）",
  "tooltip.diagAxialColor.desc": "按轴力给杆件着色：红色 = 受拉，蓝色 = 受压。粗细与大小成正比。",
  "tooltip.diagColorMap.title": "色谱图",
  "tooltip.diagColorMap.desc": "按所选内力（弯矩、剪力、轴力或 σ/fy 比值）用色阶给杆件着色。",
  "tooltip.supFixed.title": "固定支座",
  "tooltip.supFixed.desc": "约束水平位移（ux）、竖向位移（uy）和转角（θ）。不允许任何运动。",
  "tooltip.supPinned.title": "铰支座",
  "tooltip.supPinned.desc": "约束 ux 和 uy，但允许转动。杆件在该处可自由转动。",
  "tooltip.supRollerX.title": "滚动支座 X",
  "tooltip.supRollerX.desc": "仅约束 uy（竖向）。允许水平移动和转动。典型的“滚动”支座。",
  "tooltip.supRollerY.title": "滚动支座 Y",
  "tooltip.supRollerY.desc": "仅约束 ux（水平）。允许竖向移动和转动。",
  "tooltip.supSpring.title": "弹簧",
  "tooltip.supSpring.desc": "各方向刚度可配置的弹性支座（kx、ky、kθ）。用于模拟土体或柔性连接。",
