  "seismic.blocked.zone0": "表 3.1 没有为 0 区地震区划定义反应谱。第 2.5.2 条豁免 3 层或 12 m 以下的建筑，以及满足 c1、c2 和 c3 且按风荷载验算的更高建筑；Ao 组永不豁免。",
  "seismic.blocked.siteSF": "SF 类场地需要进行场地专项评估（第 2.3.2 条）。表 3.1 中没有可读取的行。",
  "seismic.assumed.faultProximity": "采用了表 3.1 中印出的近断层最小值：Na = {na}，Nv = {nv}。规范没有给出可用于提高它们的断层距离表。",
  "seismic.f1.garageSpecial": "表 3.1 将车库标注为 (*)：需要按所有空间均被占用并采用真实车辆重量进行荷载分析，而不是采用同时系数。",
  "seismic.derivation.weight": "W = D + f1·L + f2·S = {dead} + {f1}·{live} + {f2}·{snow} = {total} kN（式 3.15）。",
  "seismic.derivation.taOnly": "Ta = Cr·H^x = {cr}·{h}^{x} = {ta} s（式 6.8，表 6.2）。",
  "seismic.derivation.tComputed": "采用计算得到的周期 T = {computed} s；它低于 Cu·Ta = {cu}·{ta} = {limit} s 的限值（式 6.7）。",
  "seismic.derivation.tCapped": "计算得到的周期 {computed} s 超过式 6.7 的限值：改用 Cu·Ta = {cu}·{ta} = {limit} s。",
  "seismic.derivation.cPlateau": "T = {t} s ≤ T2 = {t2} s，因此 C = 2.5·Ca·γr/R = {sa}·{gammaR}/{r} = {c}（式 6.3）。",
  "seismic.derivation.cSpectrum": "T = {t} s > T2 = {t2} s，因此 C = Sa·γr/R = {sa}·{gammaR}/{r} = {c}（式 6.4）。",
  "seismic.derivation.cFloorNearFault": "3 区和 4 区的式 6.5 下限起控：C = 0.8·as·Nv/R = 0.8·{as}·{nv}/{r} = {c}。",
  "seismic.derivation.cFloorLowZone": "0 区、1 区和 2 区的式 6.6 下限起控：C = 0.11·Ca·γr = 0.11·{ca}·{gammaR} = {c}。",
  "seismic.derivation.dist": "Vo = {v0} kN 按 Wk·hk / ΣWi·hi 分配到 {levels} 个楼层，其中 ΣWi·hi = {sumWh} kN·m（式 6.11）。",
  "seismic.derivation.distTopHeavy": "T = {t} s 超过 2·T2 = {t2} s：Vo = {v0} kN 的 90 % 按 Wk·hk 分配到 {levels} 个楼层（ΣWi·hi = {sumWh} kN·m），其余 10 % 全部作用在最顶层质量上（式 6.12 和 6.13）。",
  "seismic.derivation.distNoMass": "基准标高以上没有质量：没有可分配的内容。",
  "seismic.blocked.dynamicRequired": "第 2.7.3 条规定必须采用动力方法：T = {t} s 超过 3·T2 = {limit} s（T2 = {t2} s）。无论高度如何，静力方法均不适用。",
  "seismic.blocked.heightOverTable25": "表 2.5 将 {zone} 区 {group} 组的静力方法限制在 {limit} m 以内；此建筑高 {h} m。",
  "seismic.blocked.irregular": "表 2.5 仅允许对平面和立面规则的建筑采用静力方法；此建筑已声明为不规则。",
  "seismic.blocked.aoIrregular": "表 2.5 仅在表 2.3 和 2.4 第 1a 行（无不规则性）的条件下允许 Ao 组采用静力方法；此建筑已声明为中等不规则。",
  "seismic.assumed.groupCAsB": "表 2.5 没有 C 组的列，因此按 B 组的行读取，这比 C 组的风险系数所需的要求更严格。",
