  "dsm.step1.explanation": "第一步是为结构的每个自由度（DOF）分配一个<strong>整体编号</strong>。",
  "dsm.step1.ordering": "先给<span class=\"free\">自由</span>自由度编号（0 到 {nFree}），再给<span class=\"restr\">受约束</span>自由度编号（{nFreeStart} 到 {nTotal}）。",
