  "dsm.step1.restrained": "受约束",
  "dsm.step2.explanation": "对每根杆件，在其自身坐标系中计算<strong>局部刚度矩阵</strong> [k]。",
  "dsm.step2.whyTruss": "桁架杆：仅有轴力。在局部坐标轴中只出现轴向自由度上的 EA/L；横向各行为零，也没有转动：杆件对节点完全不提供转动刚度。",
  "dsm.step2.whyHinge": "端 {end} 处有铰：该端不传递弯矩，因此其转角 θ{end} 被凝聚掉，相应的行和列消失。杆件变为一端固定一端铰支的悬臂梁：12EI/L³ 变为 3EI/L³，{other} 端的转动刚度由 4EI/L 降为 3EI/L，传递系数 2EI/L 消失。",
  "dsm.step2.whyBothHinged": "两端均设铰：杆件完全不传递弯矩，其弯曲刚度从 [k] 中消失，只剩 EA/L，与桁架杆完全一样。沿其跨度作用的荷载仍会传到节点，相当于简支梁的反力。",
  "dsm.step2.whyReleases3d": "此处释放：{list}。每个释放都会凝聚该转角：其行和列消失，在该弯曲平面内 12EI/L³ 变为 3EI/L³（另一端的 4EI/L 变为 3EI/L）。释放扭转则整个 GJ/L 块被去掉。",
  "dsm.step2.element": "杆件：",
  "dsm.step2.type": "类型",
  "dsm.step2.frameNote3d": "12×12 矩阵，含轴向刚度（EA/L）、两个平面内的弯曲（EIy、EIz）和扭转（GJ/L）。",
  "dsm.step2.trussNote3d": "6×6 矩阵（3D 桁架）：仅在 u₁、u₂ 对角线上有轴向刚度 EA/L。",
  "dsm.step2.localMatrix": "[k]：局部矩阵（{rows}×{cols}）",
  "dsm.step3.explanation": "<strong>变换矩阵</strong> [T] 将杆件局部坐标转到整体坐标系。",
  "dsm.step3.thenGlobal": "然后得到杆件的整体刚度：",
  "dsm.step3.element": "杆件：",
  "dsm.step3.cosinesNote": "在 3D 中，[T] 由杆件局部坐标系的<strong>方向余弦矩阵</strong> R = [eₓ; eᵧ; e_z] 构成。大小：{rows}×{cols}",
  "dsm.step3.transformation": "[T]：变换",
