  "matCode.label": "设计规范",
  "matCode.hint": "筛选出该规范通常引用的牌号。这并非限制：任何牌号都可以按任何规范验算。",
  "lore.cirsoc-301-2005.body": "INTI-CIRSOC，阿根廷",
  "lore.cirsoc-301-2005.since": "2005 年；第一版出自 1982 年",
  "lore.cirsoc-301-2005.trivia": "它是一部验算规范，而非独立规范：几乎原样采用 AISC 360 的方法，并使其适配阿根廷的钢材和单位。因此受过 AISC 训练的工程师一眼就能认出它，所采用的截面也取决于当地钢厂的标准化产品，IRAM 牌号与 ASTM 牌号并存。",
  "lore.aisc-360-16.body": "美国钢结构协会",
  "lore.aisc-360-16.since": "2016 年版；该规范系列可追溯到 1923 年",
  "lore.aisc-360-16.trivia": "它在同一份文件中并列给出 LRFD 和 ASD，名义强度相同，安全格式不同。这种统一发生在 2005 年；此前业界分属两份独立的规范和两个阵营。",
  "lore.aisc-360-22.body": "美国钢结构协会",
  "lore.aisc-360-22.since": "2022 年版",
  "lore.aisc-360-22.trivia": "增加了延性设计和超过 100 ksi 的高强钢的条款，早期版本对此完全没有涵盖。",
  "lore.en-1993-1-1-2005.body": "CEN，欧洲标准化委员会",
  "lore.en-1993-1-1-2005.since": "2005 年，取代 1992 年的 ENV 试行版",
  "lore.en-1993-1-1-2005.trivia": "各国发布国家附录，确定留待选定的参数，如分项系数、屈曲曲线和某些限值，因此仅凭「EN 1993」无法确定一次计算。同一根梁在一个国家可以通过，在另一个国家则不通过，这是合理的。",
  "lore.nbr-8800-2008.body": "ABNT，巴西",
  "lore.nbr-8800-2008.since": "2008 年，取代 1986 年版",
  "lore.nbr-8800-2008.trivia": "1986 年版采用容许应力法；2008 年版改用极限状态法，并与 AISC 和欧洲规范高度接近。NBR 8800:2024 是现行修订版。",
  "lore.cirsoc-303-2009.body": "INTI-CIRSOC，阿根廷",
  "lore.cirsoc-303-2009.since": "2009 年",
  "lore.cirsoc-303-2009.trivia": "CIRSOC 301 的冷弯型钢配套规范，沿用 AISI 的方法。薄壁在屈服之前就会局部屈曲，因此需要单独的规范，而不是一个章节。",
  "lore.aisi-s100-16.body": "美国钢铁协会",
  "lore.aisi-s100-16.since": "2016 年；第一部冷弯型钢规范出自 1946 年",
  "lore.aisi-s100-16.trivia": "引入了直接强度法，作为有效宽度法的完整替代方案：不再逐个折减板件，而是计算整个截面的屈曲荷载，并据此设计。",
  "lore.en-1993-1-3-2006.body": "CEN",
  "lore.en-1993-1-3-2006.since": "2006 年",
  "lore.en-1993-1-3-2006.trivia": "适用于壁厚约 1 mm 的冷弯构件，以及更薄的压型板。",
  "lore.nbr-14762-2010.body": "ABNT，巴西",
  "lore.nbr-14762-2010.since": "2010 年",
  "lore.nbr-14762-2010.trivia": "巴西的冷弯型钢规范，围绕 NBR 7008 的 ZAR 镀锌钢牌号编写。",
  "lore.en-1999-1-1-2007.body": "CEN",
  "lore.en-1999-1-1-2007.since": "2007 年",
  "lore.en-1999-1-1-2007.trivia": "欧洲规范 9 是欧洲规范中最新的一部。铝没有屈服平台，因此按 0.2% 条件屈服强度设计，并且必须考虑热影响区：焊接铝构件会使局部强度降低一半，这是任何钢结构规范都无需说明的。",
  "lore.adm-2020.body": "美国铝业协会，美国",
  "lore.adm-2020.since": "铝设计手册 2020 年版",
  "lore.adm-2020.trivia": "采用 E = 69,600 MPa 和 nu = 0.33，而欧洲规范 9 为 70,000 和 0.30。同一种金属，两部规范，两个模量，差异在于标定，而非物理。",
  "lore.cirsoc-701-2010.body": "INTI-CIRSOC，阿根廷",
  "lore.cirsoc-701-2010.since": "2010 年",
  "lore.cirsoc-701-2010.trivia": "阿根廷的铝结构规范，沿用美国 ADM 的传统，而非欧洲的传统。",
  "lore.en-1993-1-4-2006.body": "CEN",
  "lore.en-1993-1-4-2006.since": "2006 年",
  "lore.en-1993-1-4-2006.trivia": "不锈钢同样没有屈服平台：其应力-应变曲线是逐渐圆滑过渡的，因此碳钢的屈曲曲线不适用。这种圆滑过渡也使它对局部屈曲的容忍度高于其强度本身所显示的程度。",
  "lore.aisc-design-guide-27.body": "AISC，美国",
  "lore.aisc-design-guide-27.since": "2013 年",
  "lore.aisc-design-guide-27.trivia": "这是设计指南而非规范，美国没有强制性的不锈钢结构规范，该指南填补了这一空白。",
  "lore.cirsoc-201.body": "INTI-CIRSOC，阿根廷",
  "lore.cirsoc-201.since": "2005 年，2025 年有修订版；该系列始于 1982 年",
  "lore.cirsoc-201.trivia": "改编自 ACI 318，因此与其共用弹性模量表达式 E = 4700·√f'c。阿根廷的混凝土按其特征圆柱体强度指定，因此 25 MPa 记为 H-25。",
  "lore.en-1992-1-1.body": "CEN",
  "lore.en-1992-1-1.since": "2004 年",
  "lore.en-1992-1-1.trivia": "混凝土同时用圆柱体强度和立方体强度命名：C25/30 是同一种混凝土，而不是二选一，因为同一材料的立方体试验读数更高。其弹性模量取自平均强度，因此同一等级下远高于 ACI 的结果。",
  "lore.aci-318.body": "美国混凝土协会",
  "lore.aci-318.since": "现行版本为 2019 年版；第一版出自 1910 年",
  "lore.aci-318.trivia": "「318」只是委员会编号，沿用至今。强度以 psi 指定，因此换算为公制会得到奇怪的数值：4000 psi 是 27.6 MPa，而不是 28。",
  "lore.nbr-6118.body": "ABNT，巴西",
  "lore.nbr-6118.since": "2014 年，2023 年修订",
  "lore.nbr-6118.trivia": "其弹性模量表达式随骨料类型变化：花岗岩、玄武岩、石灰岩和砂岩各有自己的系数。这里的其他规范都没有这样做，它可使 E 变化 30%。",
  "lore.en-338.body": "CEN",
  "lore.en-338.since": "1995 年，2016 年修订",
  "lore.en-338.trivia": "按强度等级而非树种划分：C24 无论是挪威云杉还是欧洲赤松，性能都相同。数字是以 MPa 表示的抗弯强度特征值，C 代表针叶材，D 代表阔叶材，因此 D30 与 C30 的抗弯性能相同，重量却相差很大。",
