  "stress.panelTitle": "截面分析",
  "stress.close": "关闭（Esc）",
  "stress.moveAlongElem": "沿杆件移动（x/L）",
  "stress.forces3dHelp": "此截面处的 3D 内力。\nN = 轴力（+ 受拉，- 受压）\nVy = XY 平面内的剪力（产生 Mz）\nVz = XZ 平面内的剪力（产生 My）",
  "stress.moments3dHelp": "Mx = 扭矩\nMy = 绕局部 y 轴的弯矩（沿截面高度弯曲，使用 Iy）\nMz = 绕局部 z 轴的弯矩（沿截面宽度弯曲，使用 Iz）\n默认未旋转的高截面：My 为强轴/竖向，Mz 为弱轴/横向，截面转动时这两者随截面一同旋转。\n显示的 My 为正时，局部 +z 一侧受拉。显示的 Mz 为正时，局部 −y 一侧受拉。",
  "stress.rotDecompHelp": "截面转角分解（{angle}°）。\nVy、Vz = 转动后局部坐标轴上的剪力分量",
  "stress.rotMomentHelp": "按截面转角分解弯矩 M。\nMy = M·cos(α)（α=0 时为沿截面高度/强轴弯曲）\nMz = M·sin(α)（α=0 时为沿截面宽度/弱轴弯曲）\nα = {angle}°",
  "stress.forces2dHelp": "杆件此截面处的内力。\nN = 轴力（+ 受拉，- 受压）\nV = 横向剪力\nM = 弯矩（+ 下部受拉，底部受拉）",
  "stress.criticalSections": "控制截面",
  "stress.criticalSectionsHelp": "沿杆件需要验算应力的位置。\n\n包括最大弯矩点（V=0）、支座、集中荷载处和中间点。\n点击各标签即可跳转到相应截面。",
  "stress.noGeomMsg1a": "暂无 ",
  "stress.noGeomMsg1b": " 的精确轮廓，因此无法为其计算应力分布、莫尔圆和破坏准则。",
  "stress.cpInKern": "在截面核心内：σ 同号",
  "stress.naOutside": "中性轴 {arrow} 在截面外",
  "stress.rotSuffix": "（转角 {angle}°）",
  "stress.noGeomMsg2": "这是数据缺失造成的限制，而非截面本身的属性：该型材定义完整，整体分析正常使用其公布的数值。",
  "stress.noGeomMsg3": "除 MC 外，所有截面库系列都支持详细分析。请指定其中一种，或用明确的尺寸构建截面。",
  "stress.amorphMsg1": "所选截面为<strong>任意截面</strong>（没有定义几何形状）。",
  "stress.amorphMsg2": "任意截面不支持应力分布分析、莫尔圆或破坏准则。",
  "stress.amorphMsg3": "如需启用截面分析，请指定标准型材或构建具有几何形状的截面。",
  "stress.compositeMsg": "该截面由多种材料组合而成。其特性为换算截面的特性，而详细应力场只针对单一材料计算，因此不予显示。结果中的杆件应力已考虑各材料的作用。",
  "stress.stressState": "应力状态",
  "stress.sigmaBiaxHelp": "双向正应力（纳维公式）：\nσ = N/A + Mz·y/Iz − My·z/Iy\n\n式中的 y、z 是所选纤维在杆件局部坐标系中的坐标。式中弯矩取求解器符号，与面板上方所显示的弯矩符号相反。\n正 = 拉（红色）\n负 = 压（蓝色）",
  'stress.tauTotalHelp': '仅有横向剪应力或仅有扭转剪应力时的应力大小。',
  'stress.combinedShearRefused': '在扭转剪应力和横向剪应力均不为零的位置，无法提供合成剪应力、派生应力及验算结论。',
  "stress.vonMisesHelp": "von Mises 准则（畸变能）：\nσvm = √(σ² + 3τ²)\n\n适用于钢材和延性金属。\n百分比表示 fy 的利用程度。",
  "stress.trescaHelp": "Tresca 准则（最大剪应力）：\nτmax = √((σ/2)² + τ²)\n\n比 von Mises 保守约 15%。\n等价形式：2τmax ≤ fy",
  "stress.rankineHelp": "Rankine 准则（最大正应力）：\nmax(|σ₁|, |σ₃|) ≤ fy\n\n适用于脆性材料（混凝土、岩石）。\n对于钢材，宜采用 von Mises。",
  "stress.neutralAxis": "中性轴：",
  "stress.neutralAxis3dHelp": "σ=0 处的组合中性轴。\n在双向弯曲（Mz 和 My）下，中性轴可能是倾斜的。\nθ 为与 Z 轴（水平）的夹角。",
  "stress.sigma2dHelp": "正应力（纳维公式）：\nσ = N/A + M·y/I\n\n正 = 拉（红色）\n负 = 压（蓝色）\n\n取决于所选纤维（y）。",
  "stress.tauMassiveHelp": "剪应力（Jourawski 公式）：\nτ = V·Q(y) / (I·b)\n\nQ(y) = y 以上部分面积的一次矩。\n最大值在中性轴处，自由边缘处为零。\n矩形截面中呈抛物线分布。\n\n假定：τ 沿宽度 b 均匀分布。\n对于宽截面（b ≈ h），这只是近似；\n实际值沿 z 方向变化（中心处最大）。",
  "stress.tauThinHelp": "剪应力（Jourawski 公式）：\nτ = V·Q(y) / (I·b)\n\nQ(y) = y 以上部分面积的一次矩。\n最大值在中性轴处，自由边缘处为零。\n\n对于薄壁型材，假定\nτ 沿厚度均匀分布是非常准确的。",
  "stress.neutralAxisLabel": "（中性轴）",
  "stress.note2dTauOnly": "2D 分析：仅有剪力 V 产生的 τxy",
  "stress.note2dNoTorsion": "无扭转（T=0）或平面外剪力（Vz=0）",
  "stress.neutralAxis2dHelp": "中性轴（σ = 0）：\ny_NA = -N·Iz / (A·M)\n\n正应力为零的位置。\n正 = 位于形心上方。\n若 N=0，中性轴通过形心（y=0）。",
  "stress.centralCore": "截面核心",
  "stress.centralCoreHelp": "截面核心是截面的几何属性。\n它界定了 N 作用时 σ 不变号的范围。\n在截面上启用 CC 按钮即可显示。",
  "stress.ccDesc1": "<strong>截面核心</strong>是截面的几何属性，与所施加的荷载无关。",
  "stress.ccDesc2": "它界定了形心周围的区域：在该区域内作用轴力 N 时，正应力 σ 不会变号。若压力中心落在截面核心内，则整个截面处于纯拉或纯压状态。",
  "stress.ccLimitZ": "沿水平轴",
  "stress.ccLimitY": "沿竖向轴",
  "stress.ccEquations": "公式",
  "stress.ccEqDesc": "对于距形心 <em>d</em> 处的每根最外侧纤维，截面核心的顶点位于：",
  "stress.ccEqWhere": "其中 W = 截面模量，A = 面积，I = 惯性矩，d = 到最外侧纤维的距离。",
  "stress.sectionLabel": "截面：",
  "stress.ccShapeLabel": "截面核心形状：",
  "stress.shapeRect": "矩形",
  "stress.shapeIH": "I/H 截面",
  "stress.shapeCHS": "空心圆（CHS）",
  "stress.shapeRHS": "空心矩形（RHS）",
  "stress.shapeT": "T 形",
  "stress.shapeL": "L 形（角钢）",
  "stress.shapeC": "C 形（槽钢）",
  "stress.coreCircular": "圆形",
  "stress.coreHexagonal": "菱形",
  "stress.coreDiamond": "菱形",
  "stress.ccRectNote": "菱形，半轴为 e<sub>y</sub> = h/6 和 e<sub>z</sub> = b/6",
  "stress.ccIHNote": "双轴对称的尖角 I/H 截面由翼缘外角控制，截面核心为菱形。沿竖向和横向的半轴分别为 e<sub>y</sub> = I<sub>z</sub>/(A·h/2) 和 e<sub>z</sub> = I<sub>y</sub>/(A·b/2)。",
  "stress.ccCHSNote": "半径为 R<sub>cc</sub> = I<sub>z</sub>/(A·R) = R/4 的圆（实心截面）",
  "stress.ccDefaultNote": "菱形，e<sub>y</sub> = I<sub>z</sub>/(A·y<sub>max</sub>)，e<sub>z</sub> = I<sub>y</sub>/(A·z<sub>max</sub>)",
  "stress.fiberY": "纤维 y：",
  "stress.fiberZ": "纤维 z：",
  "stress.fiberYZ3dHelp": "滑块按截面图中的坐标选取纤维。\n图中 y（高度）对应杆件局部 z，代入 My·z/Iy 项。图中 z（宽度）对应杆件局部 y，代入 Mz·y/Iz 项。\n黄点表示所选纤维。",
  "stress.fiberY2dHelp": "截面内求应力的高度位置。\ny = 0 为中心（N=0 时即中性轴）。\n移动滑块可从底部纤维扫描到顶部纤维。\n在两端极值处，正应力最大，剪应力最小。",
  "results.analysis3dTooltip": "3D 分析（每节点 6 个自由度）",
