  "tour.welcomeTitle": "欢迎使用 Stabileo",
  "tour.welcomeDesc": "一款免费的结构分析程序。<br/><br/>通过这份快速指南，您只需几步就能学会建立并求解一个结构。",
  "tour.modeToggleTitle": "三种模式，一个平台",
  "tour.modeToggleDesc": "<strong>基础</strong>：2D 和 3D 结构分析，含内力图、应力和高级功能。<br/><strong>教学</strong>：通过分步练习学习结构分析。<em>（开发中）</em><br/><strong>PRO</strong>：完整的建筑分析和报告；规范设计需单独开启，仍在开发中。<br/><br/>本导览将继续在<strong>基础</strong>模式下进行。",
  "tour.buildOptionsTitle": "建立您的结构",
  "tour.buildOptionsDesc": "有三种方式创建模型：<br/><br/>&#x2022; <strong>工具</strong>：像画图软件一样绘制节点、杆件、支座和荷载<br/>&#x2022; <strong>右侧面板</strong>：直接输入数值数据<br/>&#x2022; <strong>预置示例</strong>：最快的上手方式<br/><br/>建议从示例开始。我们走吧 &#x2192;",
  "tour.examplesTitle": "加载示例",
  "tour.examplesDesc3D": "选择任意示例即可立即加载。<br/><br/>您可以求解 Stabileo 2D 具备的所有模型（桁架除外）。<br/><br/>另外还有<strong>3D 示例</strong>，可充分利用三个维度。<br/><br/>也可以使用下方按钮加载推荐的示例。",
