  "tour.manualToolsMaterials": "您还可以在右侧面板中更改<strong>材料</strong>和<strong>截面</strong>。",
  "tour.rightPanelTitle": "右侧面板",
  "tour.rightPanelDesc": "在这里可以查看和编辑模型的全部数据：<br/><br/>&#x2022; <strong>节点</strong>：各点的坐标<br/>&#x2022; <strong>杆件</strong>：带有材料和截面的杆<br/>&#x2022; <strong>材料</strong>：E、ν、fy 等特性<br/>&#x2022; <strong>截面</strong>：选择商品型材或创建自定义截面<br/>&#x2022; <strong>支座</strong>：各支座的类型和约束<br/>&#x2022; <strong>荷载</strong>：所施加的力和分布荷载<br/>&#x2022; <strong>组合</strong>：荷载组合<br/>&#x2022; <strong>结果</strong>：求解后出现<br/><br/>点击任意字段即可直接编辑。",
  "tour.solveTitle": "求解！",
  "tour.solveDesc": "当结构具有节点、杆件、支座和至少一个荷载后，点击<strong>求解</strong>。<br/><br/>程序采用<strong>直接刚度法</strong>求解。<br/><br/>可使用下方按钮或侧边栏中的按钮。",
  "tour.solveBtn": "求解",
  "tour.resultsTitle": "结果",
  "tour.resultsDesc": "在这里可以查看分析结果：<br/><br/><strong>变形图</strong>：结构放大的变形形状<br/><strong>弯矩 / 剪力 / 轴力</strong>：每根杆的特征内力图<br/><strong>轴力颜色</strong>：拉（红）与压（蓝），适用于桁架<br/><strong>云图</strong>：根据各内力大小绘制的热力图<br/><br/>可尝试在它们之间切换来探索。",
  "tour.navigateTitle": "浏览模型",
  "tour.navigateDescMobile": "用两指<strong>平移</strong>和<strong>缩放</strong>。<br/><br/>在右上角可点按<strong>适应</strong>图标，使模型适应屏幕。<br/><br/>点按左上角的 <strong>📊</strong> 按钮，可打开显示结果和内力图的浮动面板。",
  "tour.navigateDescDesktop": "使用<strong>平移</strong>工具，拖动鼠标即可在画布上移动。<br/>使用滚轮缩放。<br/><br/>在右上角可点击<strong>适应</strong>图标，使模型适应屏幕。",
  "tour.navigateDesc3DExtra": "该选项下方还有更多工具：预设视图（顶视、前视、侧视）、透视/正交、剖切平面和测量。",
  "tour.queryResultsTitle": "查询各点结果",
  "tour.queryResultsDescMobile": "在<strong>应力</strong>模式下启用<strong>↖ 选择</strong>工具，点按杆件即可查看内力。<br/><br/>也可以直接将手指移近内力图，查看该点的数值。",
  "tour.queryResultsDescDesktop": "在<strong>应力</strong>模式下启用<strong>选择</strong>工具，点击杆件即可查看完整的内力。<br/><br/>也可以直接将鼠标移近内力图，查看该点的数值。",
  "tour.advancedTitle": "高级分析",
  "tour.advancedDesc": "用于超越基本杆件分析的工具。<br/><br/>点击每个工具右侧的 <strong>(?)</strong> 可查看其作用。",
  "tour.advancedDesc3DExtra": "另外，Stabileo 2D 目前有更多的高级功能。",
  "tour.advancedDescBeta": "请注意，这些功能仍在开发中。欢迎反馈问题。",
  "tour.peek3dTitle": "在 3D 中查看",
  "tour.peek3dDesc": "您刚才在 2D 中分析的结构，同样可以在 <strong>3D 模式</strong>下使用。<br/><br/>用鼠标（移动端用两指）旋转模型，可从任意角度查看。<br/><br/>所有内力图、变形图和应力分析在 3D 中同样可用。<br/><br/>准备好后，点击下一步返回 2D。",
  "tour.configProjectTitle": "设置与项目",
  "tour.configProjectDesc": "<strong>设置</strong>：显示选项，包括网格、标签、单位和<strong>实时计算</strong>（编辑结构时自动重新计算）。<br/><br/><strong>项目</strong>：保存您的工作，分享链接让任何人查看您的结构，并导出报告（Excel、PDF、PNG、CSV）。<br/><br/>DXF 和 SVG 的导入/导出工具正在开发中。",
  "tour.feedbackTitle": "报告问题或提出改进建议",
  "tour.feedbackDesc": "发现了错误或有想法？<br/>点击此按钮向我发送报告。<br/><br/>您模型的当前状态会自动附上，以便我重现您的问题。",
  "tour.goodbyeTitle": "感谢使用 Stabileo :)",
  "tour.goodbyeDesc": "希望它对学习和分析结构有所帮助。<br/><br/>如果您喜欢，请把链接分享给同事和朋友。<br/><br/><em style=\"color:#4ecdc4; font-style:normal\">Bauti</em>",
