  "knownIssue.exportHeading": "安全警告",
  "knownIssue.NUM-INVARIANCE": "接近奇异的模型，其精度或机构判定可能随单位和方位而改变。现有的条件数或稳定性诊断表明本次求解接近奇异；设计之前请独立验证稳定性",
  "knownIssue.LIN-SMALL-DISPLACEMENT": "某个转角或某根杆件的相对位移超过 0.1 rad，即线性分析的小位移筛查限值：在该角度下，一阶理论所略去的项，例如弦长缩短 1 − cos θ ≈ 0.5 %，可能不再可以忽略。请检查几何变化是否可以接受：某个支座、弹簧或释放可能使模型的一部分近乎自由；否则请使用非线性分析",
  "knownIssue.LIN-SECOND-ORDER": "轴向压力占临界荷载的相当比例：二阶效应可能使这些线性位移和弯矩放大超过 10 %（N/Ncr > 0.075，CIRSOC 301 附录 7）。在将这些弯矩用于设计之前，请进行 P-Δ 或二阶分析",
  "knownIssue.LIN-SECOND-ORDER-NEAR": "轴向压力接近二阶限值（N/Ncr 大于 0.047，即限值 0.075 除以 CIRSOC 301 中最大的荷载系数 1.6）：放大该工况的组合可能会越过该限值。请用 P-Δ 或二阶分析检查这些组合",
  "knownIssue.LIN-SECOND-ORDER-UNBOUNDED": "杆件受压，且仅凭杆件无法界定临界荷载，因此不能确定二阶效应是否使这些线性位移和弯矩放大超过 10 %。在将这些弯矩用于设计之前，请进行 P-Δ 或二阶分析",
  "containment.more": "更多",
  "containment.less": "收起",
  "knownIssue.CERT-MECHANISM": "整体层面的证书可能认证了一个人为的或没有刚度支撑的转动。请独立验证机构；较小的代数误差界并不能证明结构稳定",
  "knownIssue.PD-SPAN-AXIAL": "P-Δ 分析根据每根杆件的平均轴力构造其几何刚度，因此在轴向跨间荷载作用下沿杆件变化的压力，可能会低估二阶放大。请细分受荷杆件，并检查结果是否收敛。",
  "knownIssue.SH-MITC4-DISTORTION.warning": "畸变的 MITC4 单元可能出现膜弯曲锁定。请验证网格收敛性；显著的膜弯曲结果将被暂不提供。",
  "knownIssue.SH-MITC4-DISTORTION": "结果暂不提供：畸变的 MITC4 四边形单元在膜弯曲中的刚度可能偏大约十倍。请用矩形单元重新划分网格，并检查网格收敛性",
  "knownIssue.SH-WARPED-MITC4": "结果暂不提供：这些 MITC4 壳的扭曲程度超出了实测的 5 % 精度范围。在扭曲（翘曲）曲面上，MITC4 的柔度可能偏大超过 5 %，最多约为两倍，且加密网格并不能减小误差。请用曲面壳单元对扭曲区域建模",
  "knownIssue.SH-WARPED-MITC4.warning": "位于扭曲（翘曲）曲面上的 MITC4 壳，其柔度可能偏大约 1.5 % 至 5 %，且加密网格并不能减小误差。请用曲面壳单元验证扭曲区域。",
  "knownIssue.SH-WARPED-MITC9": "结果暂不提供：这些 MITC9 壳的扭曲程度超出了实测的 5 % 精度范围。在扭曲（翘曲）曲面上，MITC9 的柔度可能偏大超过 5 %，最多约为 2.5 倍，且加密网格并不能减小误差。请用曲面壳单元对扭曲区域建模",
  "knownIssue.SH-WARPED-MITC9.warning": "位于扭曲（翘曲）曲面上的 MITC9 壳，其柔度可能偏大约 1.5 % 至 5 %，且加密网格并不能减小误差。请用曲面壳单元验证扭曲区域。",
  "knownIssue.PL-2D-INVARIANCE": "结果暂不提供：2D 塑性倒塌系数可能随编号、杆件方向或单位而变化，最多可达 4.6 倍。请使用经独立验证的倒塌分析",
  "knownIssue.SH-MITC4-CONVERGENCE": "MITC4 壳的基准算例显示刚度偏大，且误差随网格加密而增大。设计之前请独立验证壳的响应。",
  "knownIssue.BU-ACCURACY": "3D 屈曲系数可能偏高而不保守。设计之前请独立验证临界系数。",
  "knownIssue.BU-UNRESOLVED-MODE": "屈曲模态 {modes} 未得到解析：轴力中的舍入误差可使其几何功变化超过 1 %，通常是因为没有可解析压力的杆件驱动了这些模态。它们的荷载系数不可靠，未经独立验证不得使用。",
  "knownIssue.BU-BOUND": "结果暂不提供：计算得到的屈曲系数位于其经认证的界限之外。显示的系数和证书均不得用于设计",
  "knownIssue.SP-17": "各向异性连接器的横向轴不能由用户指定方向，且可能随方向突然变化。使用这些结果之前，请独立验证弹簧方向",
  "knownIssue.FR-5": "翘曲杆件在节点处共用一个翘曲自由度。完全传递翘曲可能使真实连接过度约束；请独立验证其构造和翘曲约束",
  "analysisValidity.cable": "结果暂不提供：索单元 {elements} 需要索分析来保证仅受拉的行为。本分析将索视为可以承受压力的杆。",
  "analysisValidity.contact": "结果暂不提供：冻结的接触 {elements} 在接触容差范围内不满足承压、脱开和无拉力条件。请修改接触模型或迭代设置后重新求解。",
  "analysisValidity.member": "结果暂不提供：冻结的单向杆件 {elements} 的轴力在按比例缩放的接触容差范围内与其行为不符。请修改接触模型或迭代设置后重新求解。",
  "analysisValidity.contactTolerance": "结果暂不提供：接触容差必须为有限的正数。请设置正的接触容差后重新求解。",
  "knownIssue.SP-14": "在索分析之外，索单元可能像桁架杆一样承受压力。请核对索的拉力，并对松弛情形使用仅受拉的索分析",
  "knownIssue.NL-13": "接触分析可能冻结一个来回振荡的间隙，同时报告收敛。请独立验证接触状态和平衡",
  "knownIssue.HARM-TRUNCATION": "采用振型叠加法的谐响应分析，在接近或高于第一个被略去振型的频率处：被略去的振型在该处未得到修正，幅值和相位可能出现数倍的巨大误差。请勿将这些频率用于设计；请用直接求解法独立验证",
  "knownIssue.MD-ORTHOGONALITY": "3D 模态分析可能返回非正交或重复的振型。有效质量、反应谱组合以及采用振型叠加法的谐响应可能出现数倍的巨大误差；请独立验证振型基",
  "knownIssue.TH-RECIPROCITY": "线性时程分析的互易性检验曾出现高达 33 倍的偏差。受影响的输入类型尚未查明；设计前请独立验证该响应",
  "knownIssue.RC-NM-PAIRING": "该柱验算将某一组合的轴力与另一组合的弯矩配对，在界限点以下可能偏于不安全。请在每个指定组合下分别验算该柱。",
  "knownIssue.NL-DYNAMIC-GAPS": "材料非线性分析在某一增量步未收敛后可能继续进行；梁的动力分析忽略了弯曲转动惯量。请独立验证收敛性和深梁（高跨比大的杆件）的响应。",
  "knownIssue.PL-3D-CERTIFICATE-MISMATCH": "3D 塑性增量分析得到的原始倒塌系数落在认证区间之外。返回的倒塌系数为经认证的下限。增量步和塑性铰保留求解器的原始值，不在该区间的认证范围内。",
  "plasticDiag.resourceBudget": "塑性认证因超出资源预算而被拒绝",
  "knownIssue.PL-3D-INVARIANCE": "曲梁 3D 塑性倒塌系数可能与编号顺序有关。请独立验证倒塌荷载。",
  "knownIssue.NL-5": "材料非线性结果为近似值：该模型采用整根杆件的割线刚度而非塑性理论，因此响应在首次屈服时发生跳变。请用塑性倒塌分析核对倒塌荷载系数",
  "knownIssue.NL-3": "在该 3D 共旋分析中，某杆件的端部相对其弦线转过超过 0.02 rad。其杆端力忽略了一项有限转动项，该项误差约按转角的一半乘以杆端弯矩增长；请将变形最大的杆件拆分为更短的杆件，直至该警告消失",
  "thermalDefault.alpha": "这些温度作用未给出热膨胀系数，因此假定 α = 12·10⁻⁶ /°C（钢材的取值）；请为材料指定其 α（混凝土约为 10·10⁻⁶，铝为 23·10⁻⁶）",
  "thermalDefault.depth": "这些温度梯度未给出截面高度，因此假定为等效实心矩形的高度 √(12·I/A)；该值仅对实心矩形是精确的（对 IPE 截面，梯度弯矩约偏低 30 %）：请为截面指定其真实高度",
