  "edu.author.helpCharEx": "学生看到：\n  Mmax = [____] kN·m\n确认后，其答案会与求解器的结果对照，判为正确或错误。",
  "edu.author.helpDiagWhat": "关于杆件某一特定点上内力图数值的问题。它们让学生读取内力图，而不仅仅是找出最大值。",
  "edu.author.helpDiagEx": "例如，在杆件 1 的中点问「跨中弯矩是多少？」。学生以数字作答。",
  "edu.author.helpShapeWhat": "学生在不计算数值的情况下选择每个内力图的形状。这训练他们认识到分布荷载产生抛物线形弯矩和线性剪力。",
  "edu.author.helpShapeEx": "学生看到四个选项：零、常数、线性、抛物线，并为每个内力图选择一个。",
  "edu.author.helpKinWhat": "学生判断结构是静定还是超静定，以及超静定次数。您无需说明：应用会自行得出。",
  "edu.author.helpKinEx": "静定：仅凭平衡条件即可求得反力。\nn 次超静定：多出 n 个未知数，需要变形协调条件。",
