  "wb.cover.massRefs": "未带入的质量重量",
  "wb.cover.massRefsValue": "有 {n} 个质量重量作用于某个区域或分组；MassSource 工作表列出了它们，但导入无法读取区域或分组，因此只作报告并略去",
  "wb.cover.stations": "沿杆件的截面位置",
  "wb.cover.stationsEqual": "{n} 个等间距，含端点",
  "wb.cover.stationsCritical": "关键位置：四分点、荷载位置和零剪力处",
  "wb.cover.cases": "荷载工况",
  "wb.cover.combinations": "组合",
  "wb.cover.case": "工况",
  "wb.conv.axes": "整体坐标轴：X 和 Y 为水平，Z 向上，右手系。位移和反力采用整体坐标轴。",
  "wb.conv.localAxes": "杆件局部坐标轴：x 从节点 I 指向节点 J；y 和 z 依据局部 Y 向量和滚转角确定。导出的滚转角同时包含杆件滚转和截面旋转，单位为度。",
  "wb.conv.sources": "结果来源：case 和 combination 标识一个已求解的荷载工况或组合。Single（sourceId 0）是独立求解，而不是单个荷载工况。包络导出采用来源 envelope 和 id 0，并带有所显示的包络名称。Magnitude 是 SRSS 或 ABS 组合：其数值是不带符号的量值，不满足平衡，并且不计入极值和包络。",
  "wb.conv.selfWeight": "SelfWeight 记录每个自重荷载的方向、系数和作用范围。显式的工况荷载同样适用于全部荷载的求解。对于旧版项目，单独的 case 行和 single 行记录各次求解所用的自重；它们是替代关系，而非叠加关系。此工作表仅作记录，模型导入器不会读取它。",
  "wb.conv.selfWeightImport": "SelfWeight 记录自重的方向、系数和作用范围。工况规则也适用于全荷载计算，除非旧版 single 行单独定义了该计算的重力。旧版 case 行和 single 行分别用于各自的计算，两者不叠加。导入支持工况规则和旧版独立重力，并报告不受支持的作用范围。",
  "wb.conv.units": "全部采用国际单位制：m、kN、kN·m；杆件应力和模量用 MPa，壳应力用 kN/m²，壳弯矩用 kN·m/m（与屏幕所示一致）；转角用 rad，温度用 °C。每个表头的括号内标注其单位。",
  "wb.conv.displacements": "位移：每个节点按求解结果的平动 ux、uy、uz 以及绕 X、Y、Z 的转动。",
  "wb.conv.reactions": "反力：支座对结构施加的力和力矩，采用整体坐标轴；它们与所施加的荷载平衡。",
  "wb.conv.memberForces": "局部坐标轴下的杆件内力，采用求解器的符号，与屏幕上内力图所示一致：N 以受拉为正；Vy、Vz、T、My 和 Mz 与内力图的绘制方式一致。",
  "wb.conv.stations": "截面位置：沿每根杆件的各点，x 从节点 I 量起。第一个和最后一个是杆端，该处的截面内力等于杆端力。",
  "wb.conv.deflections": "挠度：每个截面位置相对于杆件变形后两端连线的位移，沿局部 y（v）和 z（w），及其合成值。",
  "wb.conv.stresses": "应力：每个截面位置处截面上的最大和最小正应力，以受拉为正。依据「geometry」读取截面轮廓；「bounds」读取其外包矩形。",
  "wb.conv.shells": "壳，位于每个单元的中心：单元局部轴（x 沿其第一条边，z 垂直于它）下的膜应力 σxx、σyy、τxy 和弯矩 mx、my、mxy，对 MITC4 四边形还有横向剪力 qx、qy。整体列将同样的应力、弯矩和剪力转到整体坐标轴；曲面四边形没有这些列。",
  "wb.conv.shellFaces": "壳表面：膜应力加上（上表面，沿局部 z 轴 z = +t/2）和减去（下表面）6M/t²，每个都给出其主应力 σ1、σ2、σ1 与局部 x 的夹角、von Mises 和 Tresca（取 σ3 = 0）。另有仅膜应力的结果。曲面壳没有恢复的弯矩或表面应力：这些单元格为空白，且不计入其极值。厚度缺失或无效时，表面单元格同样留空。",
  "wb.conv.shellNodes": "壳节点：节点周围各单元按整体分量取平均。壳角点：每个单元在其角点处自身的 von Mises 应力，按引擎报告的方式：三角形取较不利的表面，四边形取膜应力。",
  "wb.conv.envelope": "包络：对每个节点、杆端和分量，给出各组合下的最大值和最小值（没有组合时按各工况），并附产生该值的组合。",
  "wb.conv.maxima": "极值：对每个分量，给出任意位置的最大值和最小值、出现位置以及所在组合。杆件内力按截面位置读取。",
  "wb.conv.statics": "静力平衡：按每个工况和组合，给出所施加荷载的合力、反力的合力，以及二者对整体坐标原点之和；worstRelative 是相对于荷载的最大残差。",
  "wb.conv.secondOrder": "二阶：按 P-Δ 求解的组合。没有二阶平衡的组合（结构在低于其荷载时就已屈曲）没有结果行，并在此列出。",
  "wb.conv.oneWay": "单向杆件和可脱离的支座：每个结果的活动集求解，包括松弛的杆件和已脱离的支座。",
  "wb.conv.model": "模型工作表使用导入器的工作表名和列键，因此可以读回；导入器不识别的列会被跳过。截面特性即交给引擎的数值。",
  "wb.conv.text": "任何文本单元格都不以 +、-、= 或 @ 开头，电子表格会把它们当作公式：开头的负号写作减号（−）。",
  "wb.conv.precision": "数值按完整精度写出。若工作簿超出 xlsx 文件的容量，或超过四百万个单元格，则写为 zip，每个工作表一个 CSV。",
  "wb.zipped": "工作簿超出 xlsx 文件能够良好处理的大小，因此写为 zip，每个工作表一个 CSV。",
  "wb.button": "项目工作簿",
  "wb.tooltip": "全部工况和组合、模型以及约定，均为完整精度。超过 xlsx 行数上限时，输出为 CSV 的 zip。",
  "wb.stations": "截面位置",
