  "physical.desc.beam.dropped": "悬挂在楼板下方。梁顶面与楼板顶面平齐时，楼板即为其翼缘：按 T 形截面设计，位于边缘时按 L 形，翼缘宽度按规范取值。",
  "physical.desc.beam.flat": "与楼板同厚，且宽大于高。按加强的楼板板带配筋；在其宽度范围内验算抗剪。",
  "physical.desc.beam.inverted": "高出楼板，楼板搭在其底面。楼板位于受拉一侧，按矩形截面设计。",
  "physical.desc.beam.foundation": "置于地面，将柱荷载沿其轴线扩散。",
  "physical.desc.beam.tie": "将各基础连在一起，使其不致分离；受拉或受压均可工作。",
  "physical.desc.beam.strap": "使边界上的基础与相邻基础相互平衡，并承担其偏心产生的弯矩。",
  "physical.desc.beam.edge": "位于楼板边缘，一侧有翼缘：按 L 形截面设计，悬挑楼板会传给它扭矩。",
  "physical.desc.beam.steel": "钢型材，按钢结构规范验算；楼板搭在其上翼缘。",
  "physical.desc.beam.timber": "锯材或胶合木，按木构件验算。",
  "physical.desc.column.concrete": "钢筋混凝土，自下而上使用同一名称：每层有各自的截面和钢筋，在节点上方搭接。楼板搭在其整个截面上。",
  "physical.desc.column.steel": "连续的钢型材，按钢结构规范验算压弯。",
  "physical.desc.column.composite": "钢型材与混凝土，外包或填入钢管内：组合截面。",
  "physical.desc.column.timber": "木构件，按受压并考虑其屈曲验算。",
  "physical.desc.slab.solid": "厚度不变，按其跨度单向或双向配筋：底部钢筋网和支座上方的负筋。",
  "physical.desc.slab.joist": "单向密肋，配填充块和面层；沿肋方向受力。",
  "physical.desc.slab.waffle": "双向肋与空腔，柱周围为实心柱帽，剪力在此集中。",
  "physical.desc.slab.hollowCore": "单向跨越的预制板；其承载力由生产厂家提供。",
  "physical.desc.slab.composite": "带混凝土面层的组合楼承板；沿楼承板的肋方向受力。",
  "physical.desc.slab.postTensioned": "带张拉预应力筋，可平衡部分荷载。",
  "physical.desc.slab.ramp": "连接两个标高的斜板。",
  "physical.desc.wall.concrete": "双层配筋的钢筋混凝土墙，逐层叠置并使用同一名称；在其平面内受力。",
  "physical.desc.wall.masonry": "砌体墙，受压和受剪。",
  "physical.desc.wall.basement": "地下室墙，除竖向荷载外还承受土压力。",
  "physical.desc.title": "它是什么，以及如何与其余部分衔接",
