  "seisDes.substitute": "这些验算替代性地遵循 ACI 318-19 第 18 章：CIRSOC 201-2025（第 18.1 条）引用 INPRES-CIRSOC 103 Parte II 2026，而本程序未收录该规范。它们仅用于指导详图设计，不构成验证。",
