  "detailing.clash.unresolved": "碰撞未解决——钢筋 {bar} 与 {barB}，构件 {element}：净距不足 {shortfall} mm。在 {rungs} 级修复中尝试了 {tried} 次移动，全部被否决：{outside} 次因超出截面（最多 {outsideBy} mm），{depth} 次因减小已验证的有效高度（最多 {depthBy} mm），{clearance} 次因侵占其他钢筋的净距",
  "check.detailing.clash": "协调后的钢筋净距",
