  "defl.checkHintTable": "各构件规则所限定的挠度利用率。混凝土按 CIRSOC 201 表 24.2.2：限值为 L/360（屋面为 L/180）时，取活荷载引起的瞬时挠度；限值为 L/480 或 L/240 时，取安装非结构构件之后的部分（持续荷载的长期挠度加活荷载）；其他限值取总长期挠度。钢结构不乘长期系数。与设计中的验算相同。",
  "design.reason.alternativesExhausted": "构件 {elementId}：搜索所实现的配筋方案均未通过验算（{tried} 个候选：钢筋 Ø{diameters} mm，最多 {rows} 排，每个区域取前 {options} 个选项，箍筋 Ø{stirrups} mm，最多 {legs} 肢）。控制项：{limiting}。这并不表明该截面无法配筋。",
  "design.reason.exhaustedBudget": "构件 {elementId}：预算在 {tried} 个候选后终止了搜索（钢筋 Ø{diameters} mm，最多 {rows} 排，箍筋 Ø{stirrups} mm）。控制项：{limiting}。",
