  "design.reason.insufficiency.shearSectionLimit": "构件 {elementId}：{axis} 上 Vu = {demand} {unit} 超过 φ·(Vc + 0,66·√f′c·bw·d) = {capacity} {unit}（§22.5.1.2），其中 Vc 取上限 0,42·√f′c·bw·d（§22.5.5.1.1），bw = {bw} m，d 取允许钢筋所能给出的最大值 {dMax} m。任何配筋都无法提高此限值：截面不足。",
  "design.reason.insufficiency.axialCapacityAtMaxSteel": "构件 {elementId}：Pu = {demand} {unit} 超过 {capacity} {unit}，即表 22.4.2.1 的轴向承载力，取 §10.6.1.1 允许的最大配筋量（ρ = {rho}）及螺旋箍筋的系数（φ = {phi}，{poFactor}·Po）。任何配筋都无法提高此限值：截面不足。",
  "design.reason.insufficiency.minimumBarRowDoesNotFit": "构件 {elementId}：两根 Ø{barDiameterMm} 钢筋按最小净距需要 {demand} {unit}，而最小箍筋（Ø{stirrupDiameterMm}）内侧只有 {capacity} {unit}（§{clause}）。没有可行的钢筋布置：截面不足。",
