  "lateral.rolesHint": "每根梁的作用即项目所声明的：属于抗侧力体系时为主梁，不属于时为次梁。未声明的梁按主梁验算并以虚线绘制。几何会给出建议（两端均与柱或墙相接时为主梁），您可以采纳。单击梁以声明另一种作用。",
  "advanced.offsetsUnsupported": "模型声明了偏心（杆件插入点或壳偏移），而本分析在节点线上求解。为避免把居中的结果当作模型的结果，该分析未运行。静力分析和组合则包含这些偏心。",
  "detailing.lapCheck.unarranged": "{joint} 处未布置搭接：钢筋 {bar} 与 {barB}（Ø{diameter}）共用同一中心线，相距 {offset} mm，而两根相接钢筋应为 {contact} mm，共 {pairs} 对。未对并排错位和使其分开的弯折建模，因此未验算搭接与相邻钢筋之间的净距（§25.5.1.2）。",
  "detailing.lapCheck.pitch": "{joint} 处非接触搭接：钢筋 {bar} 与 {barB} 中心距为 {offset} mm，超过 {limit} mm，即所需搭接长度（{lap} mm）的 1/5 与 150 mm 两者中的较小值（§25.5.1.3），共 {pairs} 对。",
  "detailing.lapCheck.short": "{joint} 处搭接过短：钢筋 {bar} 与 {barB}（Ø{diameter}）搭接 {overlap} mm，而需要 {required} mm，按 ℓd = {ld} mm、ψt = {psiT} 的 B 级搭接（表 25.5.2.1 和 §25.5.2.2），共 {pairs} 对。",
  "detailing.lapCheck.barTooLarge": "{joint} 处不允许搭接：钢筋 {bar} 与 {barB} 为 Ø{diameter}，大于 Ø{limit}，不得搭接连接（§25.5.1.1）。",
  "detailing.lapCheck.ktr": "{joint} 处搭接未验证：fy = {fy} MPa，大于 {limit} MPa，{bar} 与 {barB} 的搭接沿其长度需要 Ktr ≥ 0.5 db 的横向钢筋（§25.5.1.5），而未计算 Ktr。",
  "detailing.lapCheck.seismic": "抗震项目中 {joint} 处搭接未验证：项目采用 INPRES-CIRSOC 103，{bar} 与 {barB} 的搭接位于构件端部，该处可能形成塑性铰（§2.2.10.1 和 §2.3.13.1）。其位置未验证。",
  "detailing.lapCheck.spacing": "{joint} 处搭接拥挤：{bar} 与 {barB} 的净距为 {clear} mm，小于 §25.2.3 的 {required} mm，而 §25.5.1.2 要求搭接与相邻钢筋之间保持该间距。",
  "detailing.lapCheck.noPartner": "{joint} 处钢筋无搭接对象：{bar}（Ø{diameter}）从楼面起始，下方没有可搭接的钢筋。",
  "detailing.lapCheck.integrity": "{joint} 处整体性钢筋被搭接：周边梁中有 {laps} 根上部钢筋在支座上搭接，{continuous} 根连续穿过（{supportArea} mm² 中的 {continuousArea} mm²）。负弯矩整体性钢筋应在跨中或其附近搭接（§9.7.7.5(b)），并且至少两根钢筋和六分之一的上部钢筋应连续（§9.7.7.1(b)）。",
