  "detailing.floorRun.shellDemandNotPerCombination": "壳的需求取自求解状态，而不是某个指定的设计组合：本程序不逐单元给出各组合的壳结果，因此不指明控制组合。杜撰一个组合名称比不给更糟。",
  "detailing.floorRun.shellDemandEnveloped": "楼板和墙的弯矩是各设计组合的带符号包络：每个面都按最不利情况设计。记录不逐面指明控制组合。",
  "detailing.floorRun.slabUnsupported": "楼板 {panel}：{reason}",
  "detailing.floorRun.slabPunchingNoCaller": "板块 {panel} 支承柱 {columns}：生成本记录时未验证楼板与柱节点处的双向（冲切）剪切，因为当时没有可由节点两侧柱轴力变化推导需求的楼板与柱调用方。现已具备；请重新生成楼层详图以获得该验算。",
  "detailing.review.notConstructible": "该组件的状态为 {state}；只有从 CONSTRUCTIBLE 起才能审核。",
  "detailing.review.engineerRequired": "必须写明审核工程师。",
  "detailing.review.provisionalOutstanding": "存在未明确接受的暂定计算：{keys}。暂定计算可以接受，但必须有意识地进行。",
  "detailing.review.provisionalNotAcknowledged": "缺少对暂定计算的明确接受。",
  "detailing.review.notRecorded": "无法记录审核。",
  "slab.maturity.promotionPath": "按规范或公认文献复现一个双向板的算例，包括其 Wood-Armer 弯矩和所得配筋。",
  "slab.maturity.leverArm": "内力臂取 0.9 d，这是低配筋楼板的常用假定。",
  "wall.maturity.promotionPath": "将轴力与弯矩相互作用与完整的相互作用图或墙的算例进行比较。",
  "wall.maturity.simplifiedInteraction": "弯矩承载力采用矩形截面分布钢筋的简化表达式，它近似于真实的相互作用曲面。",
  "detailing.slabPunching.staleAnalysis": "楼板 {panel}，节点 {node}（柱 {column}）：双向剪切未验证，因为板块的需求来自早于模型的分析。柱轴力差将取自不再描述当前结构的结果，而基于过期内力的冲切验算是对一栋不存在的建筑的验算。请重新求解并重新设计。",
  "detailing.slabPunching.oppositeRuns": "楼板 {panel}，节点 {node}（柱 {column}）：楼板在 {coverage}° 范围内与节点相接，表现为两段相对的延伸——类似板带的情形。§22.6.5.3 仅给出了内柱、边柱和角柱的 α_s，而在两个相对面上被截断的周边不属于这三者。双向剪切按未验证给出，而不是用错误的 α_s 近似。",
  "detailing.slabPunching.reEntrant": "楼板 {panel}，节点 {node}（柱 {column}）：楼板在 {coverage}° 范围内与节点相接——凹角。临界周边是 §22.6.5.3 未列出的第六种形状，因此双向剪切按未验证给出，而不是赋予属于其他几何形状的 α_s。",
  "detailing.slabPunching.noSlab": "节点 {node}（柱 {column}）在板块 {panel} 中没有楼板材料，因此没有可验算的双向剪切面。实测角度：{coverage}°。",
  "detailing.slabPunching.disjointRuns": "楼板 {panel}，节点 {node}（柱 {column}）：楼板在 {coverage}° 范围内以分离的延伸段与节点相接。临界周边不属于 §22.6.5.3 所列的三种形状之一，因此双向剪切按未验证给出。",
  "detailing.slabPunching.skewed": "楼板 {panel}，节点 {node}（柱 {column}）：楼板在 {coverage}° 范围内与节点相接，在容差内既不是 90°、180°、270° 也不是 360°。该位置无法归类为内柱、边柱或角柱，因此双向剪切按未验证给出，而不是取整到最近的已列情形。",
  "detailing.slabPunching.missingGeometry": "楼板 {panel}，节点 {node}（柱 {column}）：双向剪切需要正的有效高度、柱的平面尺寸和混凝土强度。实测厚度 {thickness} m，保护层 {cover} m，柱 {b} × {h} m，f'c {fc} MPa。验算按未验证给出，而不是基于缺失的尺寸运行。",
  "detailing.slabPunching.noColumnForces": "楼板 {panel}，节点 {node}（柱 {column}）：没有任何已求解的组合在该节点处给出柱轴力，因此无法由平衡确定传递的力。双向剪切未验算；不采用假定值。",
  "detailing.slabPunching.averageMatDepth": "楼板 {panel}，节点 {node}：双向剪切的有效高度取 {d} m，由楼板厚度减去保护层和上层钢筋网的平均钢筋直径 {diameter} mm 得到。两个方向的钢筋网实际位于不同深度，而临界周边是同一个面，因此该平均值是一个假定。",
  "detailing.slabPunching.noColumnAbove": "楼板 {panel}，节点 {node}（柱 {column}）：节点上方没有柱，因此隔离体在该面是开放的，下柱的全部轴力成为传递的差值。这是屋面节点的真实边界条件，而不是缺失的力。",
  "detailing.slabPunching.noColumnBelow": "楼板 {panel}，节点 {node}（柱 {column}）：节点下方没有柱，因此隔离体在该面是开放的，上柱的全部轴力成为传递的差值。这是柱悬挂于楼板之下的真实边界条件，而不是缺失的力。",
  "detailing.slabPunching.residualNotEstablished": "楼板 {panel}，节点 {node}（柱 {column}）：冲切隔离体在所有已求解的组合中都不平衡。最不利情况为 {combination}——轴力差 {step} kN，而直接传递并位于临界周边内的荷载为 {deducted} kN，剩余 {residual} kN。V_u 将成为被截为零的负数，这是由算术而非承载力得出的通过。双向剪切按未验证给出。",
  "detailing.slabPunching.someCombinationsUnbalanced": "楼板 {panel}，节点 {node}：{total} 个组合中有 {count} 个（{combinations}）无法使冲切隔离体平衡，已从控制组合的选择中排除。其余组合平衡，给出的验算结果来自这些组合。",
  "detailing.slabPunching.upliftNotEstablished": "楼板 {panel}，节点 {node}（柱 {column}）：组合 {combination} 的双向剪切未验证：轴力差方向相反——上柱向上拉节点的力比下柱向下压的力多 {step} kN。这是上拔冲切，是受拉面颠倒的另一种机理，而本记录所做的向下验算对此毫无说明。若取 |step| 运算会完全掩盖方向。",
  "detailing.slabPunching.someCombinationsUplift": "楼板 {panel}，节点 {node}：{total} 个组合中有 {count} 个（{combinations}）使节点处于上拔——轴力差反向——已从控制组合的选择中排除。其余组合按向下验算；上拔方向是另一种机理，未验证。",
  "detailing.slabPunching.momentTransfer": "楼板 {panel}，节点 {node}（柱 {column}）：组合 {combination} 传递 {moment} kN·m 的不平衡弯矩，双向剪力为 {shear} kN。偏心剪切的弯矩传递（§8.4.4.2）尚未实现，仅验算直接剪切可能会通过一个实际上不足的节点。该节点的双向剪切按未验证给出。",
  "detailing.floorRun.wallUnsupported": "墙 {wall}：{reason}",
  "detailing.floorRun.wallBoundaryNotImplemented": "墙 {wall}：项目绑定了抗震规范，因此可能需要边缘构件。边缘构件设计属于 INPRES-CIRSOC 103 Part II 的内容，尚未实现；非抗震的边缘构件看起来像完整的设计，但并非如此。",
  "detailing.floorRun.wallBoundaryRequired": "墙 {wall}：可能需要边缘构件，其设计尚未实现。",
  "detailing.floorRun.wallBoundaryNotTriggered": "墙 {wall}：未绑定抗震规范，因此不适用边缘构件的触发条件。",
