  "footing.ui.matConflictRow": "{a} / {b}——{cls}：实测 {measured} mm，要求 {required} mm。",
  "footing.ui.matNoConflicts": "碰撞检查未发现涉及钢筋网的冲突。{crossings} 处正交的 X/Y 交叉是设计上的接触：§25.2.1 和 §25.2.2 规定的是平行钢筋之间的净距——同一层内和平行层之间——而正交网格两者都不属于。",
  "footing.ui.matPunchingMoment.NEGLIGIBLE": "连接处的不平衡弯矩 Msc = {msc} kN·m（分量 {x} 和 {y}），低于 {threshold} kN·m 的显著性阈值：由直接剪切控制。这不是 §8.4.4.2 的验证。",
  "footing.ui.matPunchingMoment.UNSUPPORTED_MOMENT_TRANSFER_NOT_EVALUATED": "冲切未验证。该连接传递不平衡弯矩 Msc = {msc} kN·m（分量 {x} 和 {y}），超过 {threshold} kN·m 的阈值，而 §8.4.4.2 的偏心剪切弯矩传递尚未实现。底部钢筋网已验证；基础整体未验证。",
  "footing.ui.matPunchingMoment.UNSUPPORTED_MOMENT_NOT_FORMED": "冲切未验证。无法形成该连接的不平衡弯矩，因此不声称其为零。仅验算直接剪切会通过一个无人评估过弯矩的节点。",
  "footing.ui.matGeometrySteps": "实体几何说明",
  "footing.ui.matAnchorageSteps": "锚固说明",
  "footing.record.flexureGeometryNotReconciled": "底部钢筋网已设计，但其实体几何与钢筋表不一致：有 {findings} 项阻断性发现。不输出钢筋，因为与已批准钢筋表不符的钢筋网图将进入模型、图纸和导出文件，描述无人设计过的配筋。弯曲未验证。",
  "footing.record.anchorageNotEvaluated": "没有可量测的实体钢筋网，因此未评估底部钢筋的锚固。这不是锚固失败：而是缺少用于量测的几何。",
  "footing.record.topReinforcementNotEvaluated": "基础 {footing}：未评估上部钢筋。本项目中没有任何权威计算表明其不必要，因此既不声称不必要，也不设计任何上部钢筋。底部钢筋网的验证仍然成立；在此项未决期间，该基础不适合签发。",
  "footing.geometry.noLayerOrder": "未确定实体层序（{rationale}），因此没有可用于绘制钢筋的标高。若按保守的包络高度绘制，会在模型中放入无人选定标高的钢筋。",
  "footing.geometry.directionNotDesigned": "方向 {axis} 未设计（{status}），因此两个方向均不生成几何：§13.3.3 要求双向配筋，只配一半不成其为钢筋网。",
  "footing.geometry.elevationMismatch": "方向 {axis}：钢筋轴线标高对应的有效高度为 {implied} m，而设计取 {designed} m。钢筋将按与其设计不同的深度绘制。",
  "footing.geometry.countMismatch": "方向 {axis}，区域 {region}：钢筋表要求 {scheduled} 根钢筋，而布置得到 {placed} 根。不会为使图纸闭合而重新分配钢筋。",
  "footing.geometry.spacingMismatch": "方向 {axis}，区域 {region}：布置间距为 {placed} mm，而表中间距为 {scheduled} mm。",
  "footing.geometry.sideCoverShort": "方向 {axis}，区域 {region}，钢筋 {bar}：量至钢筋表面的侧面保护层为 {measured} mm，小于要求的 {required} mm。",
  "footing.geometry.bottomCoverShort": "方向 {axis}，钢筋 {bar}：量至表面的底部保护层为 {measured} mm，要求 {required} mm，距顶面还剩 {toTop} mm。",
  "footing.geometry.outsideConcrete": "方向 {axis}，钢筋 {bar}：钢筋超出混凝土 {over} mm。",
  "footing.geometry.duplicateBar": "方向 {axis}：钢筋 {a} 与 {b} 占据同一位置。",
  "footing.geometry.clearSpacingShort": "方向 {axis}：钢筋 {a} 与 {b} 之间的净距为 {measured} mm，小于 §25.2.1 的 {required} mm。这是相邻 §13.3.3.3 区域之间的间隙，任何单个区域都不会布置它。",
  "footing.geometry.providedAsMismatch": "方向 {axis}：生成的钢筋提供 {placed} cm²，而钢筋表记载为 {scheduled} cm²。",
  "footing.anchorage.insufficient": "方向 {axis}，Ø{diameter}：需要 {required} mm 的直线锚固长度，而从柱面到实体钢筋端部在{side}侧只有 {available} mm 可用——短 {short} mm。不会臆造弯钩，也不会缩减 ld。",
  "footing.anchorage.noGeometry": "没有实体钢筋网（{status}），因此无法量测从临界截面起的可用长度。",
  "footing.record.flexureDesignedNotModeled": "底部钢筋网在两个方向均已设计——需求、所需钢筋、根数和符合规范的间距——但未建模：模型、钢筋表或 CAD 交付中都没有实体钢筋。因此弯曲仍未验证，因为仍然没有可用于验算需求的配筋。",
  "footing.record.flexureDesignFailed": "底部钢筋网设计失败：在所选直径下未找到该基础可行的配筋布置。列出的条件说明了哪项要求无法满足。所选直径未被悄悄更改，也没有任何布置被报告为可接受。",
