  "footing.cad.unsupported.matGeometry": "基础 {footing}：底部和顶部钢筋网属于制图要求，而非钢筋几何。本次交付仅包含柱传力钢筋笼，不是完整的基础配筋。",
  "footing.cad.unsupported.containment": "基础 {footing}：Stabileo 不评估钢筋的包容性。外部测量是独立的观测，绝不等同于 Stabileo 的结论。",
  "footing.cad.unsupported.columnCover": "单元 {element}：此处既不要求也不评估柱保护层。",
  "footing.cad.assumption.stubTruncated": "单元 {element} 的柱段在 z = {top} m（传力钢筋笼顶部）处截断。该上表面是剖切面而非混凝土表面，无法据此测量保护层。",
  "footing.cad.assumption.sampler": "钢筋范围和界面穿越是在识别圆弧的实际中心线采样器上以 {tolerance} mm 的弦长容差测得的，与碰撞检测器所用路径相同。",
  "footing.cad.assumption.columnBaseAbove": "在分析模型中，柱单元 {element} 的底节点位于 z = {base} m，比位于 z = {top} m 的基础顶面高出 {gap} m。柱段从基础顶面起算，因为实际的插筋和起步钢筋几何正是按该标高布置的。",
  "footing.cad.assumption.aggregate": "项目中没有任何混凝土给出最大骨料粒径，因此假定为 {mm} mm。这不是规范默认值。",
  "footing.cad.refusal.footingNotFound": "没有编号为 {id} 的基础。",
  "footing.cad.refusal.nodeNotFound": "基础 {footing} 引用了节点 {node}，该节点不在模型中。",
  "footing.cad.refusal.noColumn": "基础 {footing} 未引用任何柱。没有柱就没有底面轮廓和界面，而臆造柱尺寸会挪动他人的基础。",
  "footing.cad.refusal.notDimensioned": "基础 {footing} 尚未确定尺寸。平面尺寸和厚度必须均为正值。",
  "footing.cad.refusal.rotated": "基础 {footing} 旋转了 {rotation}°。将连接换算到旋转后的基础坐标轴尚未实现，而把整体坐标轴当作局部坐标轴会使界面错位。",
  "footing.cad.refusal.eccentric": "基础 {footing} 存在平面偏心 ({b}, {l}) m。模型将其记录为基础形心的偏移，而实际的插筋几何将其用作柱中心；取值非零时两者位置不同，选择任何一个都是猜测。",
  "footing.cad.refusal.pedestal": "基础 {footing} 带有柱墩。柱墩是具有自身界面的第三个混凝土构件，本版本尚不支持。",
  "footing.cad.refusal.noAssembly": "基础 {footing} 没有配筋构造组件。请先生成基础配筋。",
  "footing.cad.refusal.noVerifier": "基础 {footing} 没有验算者身份。交付证书将不署名任何验算者，使用方无法将其与传输中丢失区分开。请运行规范验算和设计，使各构件得到验证，然后重新生成配筋；如果在该次运行之后项目规范发生了变化，之前的身份不再适用，必须按当前绑定的规范重新设计。",
  "footing.cad.refusal.noCage": "基础 {footing} 的组件中没有传力钢筋笼配筋。",
  "footing.cad.refusal.noDowels": "基础 {footing} 没有柱插筋，因此没有可导出的传力钢筋笼。",
  "footing.cad.refusal.unclassifiedBar": "基础 {footing}：这些钢筋没有本导出器能够表述的配筋类别：{bars}。把它们归入现有类别会误述它们。",
  "footing.cad.refusal.incompatibleWithV1": "基础 {footing}：组件中含有 {bars} 根钢筋，属于 RcCadHandoffV1 未声明的类别（{families}）。V1 已冻结，仅包含柱插筋和起步箍筋；将这些钢筋描述为任一类别都会误述，而省略它们会隐瞒实际存在的钢筋。请导出可包含它们的 RcCadHandoffV2。",
  "footing.cad.refusal.noStubExtent": "基础 {footing}：柱段将从 z = {base} m 延伸至 z = {top} m，这不构成实体。",
