  "proRibbon.cmdOtherCodesDesc": "在当前启用的组合下，按 AISC 360、EN 1993-1-1、AISI S100、ACI 318 或 EN 1992-1-1 验算杆件。",
  "otherCodes.pick": "规范",
  "otherCodes.family.steel": "热轧型钢和钢管",
  "otherCodes.family.coldFormed": "冷弯薄壁型钢",
  "otherCodes.family.concrete": "钢筋混凝土",
  "otherCodes.code.aisc360": "AISC 360 (LRFD)",
  "otherCodes.code.ec3": "EN 1993-1-1",
