  "otherCodes.code.aci318": "ACI 318",
  "otherCodes.code.ec2": "EN 1992-1-1",
  "otherCodes.coverage.aisc360": "双轴对称的 I 形和 H 形截面及钢管：受拉、受压（E3，并按 E7 折减细长板件）、含弯扭屈曲的受弯（F2，Cb = 1，荷载作用于上翼缘）、受剪（G2）和相关作用（H1）。受弯为非密实或细长截面、以及受剪 Cv1 < 1 的截面标记为未评估。每根杆件采用其自身给定的长度和 K。",
  "otherCodes.coverage.ec3": "I 形和 H 形截面（从热轧型钢库选取时为热轧，否则为焊接）及冷弯钢管：弯曲屈曲（表 6.2 曲线）、弯扭屈曲（6.3.2，C1 = 1，荷载作用于上翼缘）、受弯、受剪和轴力。截面等级的判定不计圆角半径；4 类 I 形和矩形钢管采用 EN 1993-1-5 有效截面，4 类圆钢管不包含在内。6.3.3 的相关作用采用附录 B 的系数，Cm = 1。受弯与剪力共同作用及腹板剪切屈曲标记为未评估。",
  "otherCodes.coverage.aisiS100": "单片带卷边 C 形截面：有效宽度（附录 1）、受压、受拉、含弯扭屈曲的受弯（F2.1）、屈服范围内的腹板受剪以及相关作用。未评估畸变屈曲，因此任何一行都不会显示为通过；受压的弯扭屈曲和弱轴受弯也未评估。Z 形截面不包含在内。",
  "otherCodes.coverage.aci318": "采用各杆件给定配筋的矩形截面：压弯（P–M 图）和带箍筋的受剪。梁按区域（支座和跨中）验算，柱按两侧钢筋验算。采用 420 MPa 钢筋和 2.5 cm 保护层，与 CIRSOC 设计相同。绕两个轴受弯的杆件不包含在内。",
  "otherCodes.coverage.ec2": "采用给定配筋的矩形梁：受弯（6.1）和受剪（6.2），γc = 1.5，γs = 1.15，αcc = 1。受弯不考虑轴力，因此柱不包含在内，轴力大于 0.1·fcd·Ac 的梁标记为未评估。采用 420 MPa 钢筋和 2.5 cm 保护层，与 CIRSOC 设计相同。",
  "otherCodes.run": "验算",
