  "frameEd.stale.count": "已保存但不再与其梁相符的梁轴线：{n}。在您逐一决定如何处理之前，配筋详图不会应用它们。",
  "frameEd.stale.redesigned": "{ids} 的钢筋在保存轴线之后发生了变化，原因是运行了设计或进行了编辑。您可以将已保存的轴线重新作为草稿，检查后再保存，也可以放弃它。",
  "frameEd.stale.geometry": "{list} 的跨度已改变。已保存轴线的位置对应于先前的几何，不会按比例缩放：请放弃它，并在当前几何上重新编辑该轴线。",
