  "loads.ec.reduction.alphaA": "αA = 5/7·ψ0 + A0/A，其中 A = {area} m²，A0 = 10 m²。αA = {alpha}，q = {l} kN/m²（EN 1991-1-1 §6.3.1.2(10)）。",
  "loads.ec.reduction.alphaN": "αn = (2 + (n − 2)·ψ0)/n，其中楼层数 n = {n}。αn = {alpha}，q = {l} kN/m²（EN 1991-1-1 §6.3.1.2(11)）。",
