  "loads.ec.reduction.ukAlphaN": "αn = 1.1 − n/10（6 至 10 层取 0.6，更高时取 0.5），其中 n = {n}。αn = {alpha}，q = {l} kN/m²（EN 1991-1-1 英国国家附件）。",
