  "loads.ec.ui.vbMap": "vb,map（m/s），见图 NA.1",
  "loads.ec.ui.windHint": "根据 qp(z) 和表 7.1 的 D 区、E 区计算各层水平力，考虑每个方向的正负两向。国家附件或场地条件另有要求时应调整 cdir、cseason 和 c0，否则均取 1。",
  "loads.ec.ui.windHintUk": "按英国附件取 vb,0 = vb,map·calt。qp(z) 按 EN 1991-1-4 的方法和地貌类别计算，未采用图 NA.7 和 NA.8。",
  "loads.ec.wind.basic": "风荷载：vb = cdir·cseason·vb,0 = {cdir} × {cseason} × {vb0} = {vb} m/s。地貌类别 {cat}，kr = {kr}，c0 = {c0}，ρ = {rho} kg/m³。qp(h = {h} m) = {qp} kPa，cs·cd = {cscd}（EN 1991-1-4 §4.2 至 §4.5）。",
  "loads.ec.wind.cpe": "风向 {dir}：h/d = {hd}（d = {d} m，b = {b} m），cpe,10 在 D 区为 {cpeD}，在 E 区为 {cpeE}（表 7.1），不相关折减系数 {f}（§7.2.2(3)）。",
  "loads.ec.wind.cscdOne": "cs·cd = 1.0 适用于高度小于 15 m 的建筑及 §6.2(1) 的其他情况。否则请输入附件 B 或 C 的数值。",
  "loads.ec.wind.noFront": "风向 {dir}：模型在该方向无迎风宽度。",
  "loads.ec.wind.notCovered": "仅由 D 区及 E 区生成各层水平力。未生成屋面压力（§7.2.3 至 §7.2.7）、内压（§7.2.9）、摩擦力（§7.5）及不对称压力引起的扭矩。",
  "loads.ec.wind.nothing": "基底以上没有楼层，或未选择风向。",
  "loads.ec.wind.ukBasic": "vb,0 = vb,map·calt = {vmap} × {calt} = {vb0} m/s。calt = 1 + 0.001·A，A = {alt} m（英国国家附件 NA.2.4）。",
  "loads.ec.wind.ukRecommendedProfile": "qp(z) 按 EN 1991-1-4 §4.3 至 §4.5 的方法和地貌类别计算。未采用英国附件图 NA.7 和 NA.8 的 ce(z)，也未采用该附件的地形修正。",
  "loads.ec.windCase": "风荷载 {dir}",
