  "loads.asce7.combo.exception1": "§2.3.1 例外 1：Lo = {lo} kN/m²，不超过 {limit} kN/m²（100 psf），且无车库或公共聚集场所。组合 3、4 和 6 中 L 的系数取 0.5。",
  "loads.asce7.combo.exception1Not": "§2.3.1 例外 1 不适用（Lo = {lo} kN/m²，限值 {limit} kN/m²，或存在车库或公共聚集场所）。L 的系数取 1.0。",
  "loads.asce7.combo.notCombined": "此版本未按 ASCE 7-22 对作用 {symbols} 进行组合。请为这些作用定义项目组合规则。",
  "loads.asce7.service.basis": "按 ASCE 7-22 附录 C 及其条文说明进行挠度和层间位移的正常使用组合：D + L，长期效应取 D + 0.5 L，使用阶段风致层间位移取 D + 0.5 L + Wa。",
  "loads.asce7.reduction.applied": "§4.7.2，式 4.7-1：KLL = {kll}，AT = {at} m²，KLL·AT = {kllAt} m²。L = {lo}·(0.25 + 4.57/√(KLL·AT)) = {l} kN/m²。",
  "loads.asce7.reduction.appliedFloor": "§4.7.2，式 4.7-1：KLL = {kll}，AT = {at} m²，KLL·AT = {kllAt} m²。计算值低于下限 {floorFactor}·Lo，取 L = {l} kN/m²。",
  "loads.asce7.reduction.assembly": "§4.7.5：聚集场所的活荷载不折减。",
  "loads.asce7.reduction.below": "§4.7.2：KLL·AT = {kllAt} m²（KLL = {kll}，AT = {at} m²），低于 {threshold} m²（400 ft²），不折减。",
  "loads.asce7.reduction.garage": "§4.7.4：仅支承一层的构件，其乘用车车库活荷载不折减。",
  "loads.asce7.reduction.garageMulti": "§4.7.4：乘用车车库中支承两层及以上的构件，活荷载最多折减 20%，且不得低于 §4.7.2 的 L。取 L = {l} kN/m²。",
  "loads.asce7.reduction.heavy": "§4.7.3：Lo = {lo} kN/m²，高于 {limit} kN/m²（100 psf），且构件仅支承一层，不折减。",
  "loads.asce7.reduction.heavyMulti": "§4.7.3：Lo = {lo} kN/m²，高于 {limit} kN/m²（100 psf）。构件支承两层及以上时，最多折减 20%，且不得低于 §4.7.2 的 L。取 L = {l} kN/m²。",
  "loads.asce7.reduction.notPermitted": "表 4.3-1 不允许折减此用途的活荷载。",
  "loads.asce7.seismic.blocked.noSpectrum": "缺少反应谱。请按场地类别，从 USGS 地震设计地理数据库输入 SDS 和 SD1（或 SMS 和 SM1）（§11.4）。ASCE 7-22 已取消 Fa 和 Fv 表。",
  "loads.asce7.seismic.blocked.noSystem": "抗侧力体系「{system}」缺少 R、Cd 和 Ω0。请从表 12.2-1 选一行或手动输入。",
  "loads.asce7.seismic.blocked.noTl": "缺少长周期过渡周期 TL（§11.4.6）。",
  "loads.asce7.seismic.blocked.noS1": "缺少 S1。请输入 USGS 地震设计地理数据库中地图给出的 1 秒周期谱加速度（§11.4.2），用于确定 E、F 类别（§11.6）和式 12.8-6 的 Cs 下限。",
  "loads.asce7.seismic.blocked.siteF": "F 类场地：ASCE 7-22 要求进行场地反应分析（第 21 章），因此不生成等效侧向力。",
  "loads.asce7.seismic.derivation.design": "设计谱（§11.4，场地类别 {site}）：输入值 SDS = {sds} g，SD1 = {sd1} g。",
  "loads.asce7.seismic.derivation.mce": "反应谱（§11.4.4，场地类别 {site}）：SDS = 2/3·{sms} = {sds} g，SD1 = 2/3·{sm1} = {sd1} g。",
  "loads.asce7.seismic.derivation.category": "风险类别 {rc}，Ie = {ie}（表 1.5-2），抗震设计类别 {sdc}（§11.6）。表 12.2-1：R = {r}，Cd = {cd}，Ω0 = {omega0}。ρ = {rho}（§12.3.4）。",
  "loads.asce7.seismic.derivation.weight": "有效地震重量 W（§12.7.2）包括自重和恒荷载、储藏区活荷载的 {share}、楼面隔墙荷载 {partition} kN/m²，以及 pf 超过 30 psf 时设计雪荷载的 {snow}。",
  "loads.asce7.seismic.derivation.period": "周期（§12.8.2）：Ta = Ct·hn^x = {ct}·{hn}^{x} = {ta} s（式 12.8-7），Cu = {cu}（表 12.8-1），T = {t} s。",
  "loads.asce7.seismic.derivation.cs": "Cs（§12.8.1.1）：SDS/(R/Ie) = {base}，周期对应的上限为 {cap}，下限 0.044·SDS·Ie ≥ 0.01 = {min}，由 S1 得到的下限为 {minS1}。Cs = {cs}。",
  "loads.asce7.seismic.derivation.baseShear": "V = Cs·W = {cs}·{w} = {v} kN（式 12.8-1）。Fx = Cvx·V，k = {k}（§12.8.3）。E 工况取 ρ·QE，其中 ρ = {rho}。",
  "loads.asce7.seismic.derivation.ev": "Ev = 0.2·SDS·D（§12.4.2.2），其中 SDS = {sds}。在 1.2 D + Ev + Eh 中加入 {kv}·D，在 0.9 D − Ev + Eh 中扣除它。",
  "loads.asce7.seismic.derivation.evZero": "SDS = {sds} 不超过 0.125，Ev 取零（§12.4.2.2，例外 1）。",
  "loads.asce7.seismic.note.notCovered": "未生成含超强系数 Ω0 的组合（§12.4.3）及扭转放大 Ax（§12.8.4.3），也未按 Cd 验算层间位移（§12.8.6、§12.12），或核查各类别的体系高度限值。",
  "loads.asce7.seismic.note.orthogonalNeedsBoth": "100% + 30% 组合（§12.5.3）需要两个方向。只选一个方向时不会生成。",
  "loads.asce7.seismic.note.rhoLowSdc": "抗震设计类别 {sdc}：§12.3.4.1 允许取 ρ = 1.0。此处使用输入值。",
  "loads.asce7.snow.assumption.ce": "假定 Ce = {ce}（表 7.3-1）。请按屋面粗糙度和暴露条件输入。",
  "loads.asce7.snow.assumption.ct": "假定 Ct = {ct}。在 ASCE 7-22 中，Ct 取决于屋面的保温热阻 R 和 pg（表 7.3-2、7.3-3）。请输入实际值。",
  "loads.asce7.snow.assumption.csCurve": "Cs 按 Ct 和屋面情况由上一版图 7.4-1 的曲线取得。ASCE 7-22 已修订该图，请核对 Cs 或手动输入。",
  "loads.asce7.snow.blocked.noPg": "缺少相应风险类别的地面雪荷载 pg（§7.2，ASCE 灾害工具）。",
  "loads.asce7.snow.derivation.pf": "平屋面雪荷载（式 7.3-1，ASCE 7-22 不含 Is）：pf = 0.7·Ce·Ct·pg = 0.7·{ce}·{ct}·{pg} = {pf} kN/m²。",
  "loads.asce7.snow.derivation.ps": "屋面坡度 {slope}°：Cs = {cs}，ps = Cs·pf = {ps} kN/m²（式 7.4-1）。",
  "loads.asce7.snow.derivation.pm": "低坡屋面，风险类别 {rc}：pm = {pm} kN/m²（§7.3.4），低于 ps = {ps} kN/m²。",
  "loads.asce7.snow.derivation.pmGoverns": "低坡屋面，风险类别 {rc}：最小值 pm = {pm} kN/m²（§7.3.4）大于 ps = {ps} kN/m²，作为本工况的均布荷载。",
  "loads.asce7.snow.unsupported.notCovered": "仅生成平衡雪荷载（或 pm）。未生成不平衡雪荷载（§7.6）、漂移积雪（§7.7、§7.8）、滑落积雪（§7.9）、雨落积雪（§7.10）和局部荷载（§7.5）。",
  "loads.asce7.wind.blocked.flexible": "柔性建筑（n1 低于 1 Hz）：尚未实现 ASCE 7-22 §26.11.5 的阵风效应系数 Gf。",
