  "loads.ec.seismic.verticalOn": "竖向分量（EN 1998-1 §4.3.3.5.2）：avg = {avg} g。未给出有关构件的周期时，将竖向设计谱的平台值 2.5·avg/q（q = {q}，§3.2.2.5(5)–(6)）施加于永久荷载，EEdz = {kv}·G。",
  "loads.ec.seismic.verticalWhole": "竖向分量作用于整个结构。§4.3.3.5.2 仅要求对跨度至少 20 m 的水平构件、长度超过 5 m 的悬臂、预应力水平构件、托柱梁和基础隔震结构考虑竖向分量。对整个结构施加是建模选择，不能作为结果上限，因为符号相反的效应可能抵消。请验算需要考虑该分量的构件。",
  "loads.ec.seismic.verticalOff": "avg = {avg} g 超过 0.25 g，但竖向分量已关闭。EN 1998-1 §4.3.3.5.2 要求对跨度至少 20 m 的水平构件、长度超过 5 m 的悬臂、预应力水平构件、托柱梁和基础隔震结构考虑竖向分量。",
  "loads.ec.seismic.verticalBelow": "avg = {avg} g 不超过 0.25 g，EN 1998-1 §4.3.3.5.2 不要求考虑竖向分量。",
  "loads.ec.seismic.verticalCombos": "每项地震组合生成四种情况（式 4.18–4.20）：水平工况主导时取 G ± {kv3}·G。竖向分量主导时，各水平分量取 {share}，同时取 G ± {kv}·G。",
  "loads.ec.ui.vertical": "竖向分量（§4.3.3.5.2）",
  "loads.ec.ui.verticalAbove": "avg = {avg} g 超过 0.25 g。跨度至少 20 m 的水平构件、长度超过 5 m 的悬臂、预应力水平构件、托柱梁和基础隔震结构必须考虑竖向分量。系统对整个结构生成此分量。",
