  "loadPlan.derivation.roofLivePart": "屋面用途为 {roof} 类，楼面用途为 {floor} 类。屋面活荷载属于使用荷载的一部分，设有独立工况，按 {roof} 类的 ψ 组合（EN 1990 表 A1.1）。两部分同时作为主导作用或同时作为伴随作用（EN 1991-1-1 §3.3.1(2)P）。",
