  "loads.ec.seismic.levelRoof": "标高 +{elevation} m：{live} kN 的楼面使用荷载取 ψE = {psiE}，{liveRoof} kN 的屋面使用荷载按其类别取 ψE = {psiRoof}。地震重量为 {weight} kN（EN 1998-1 §3.2.4、§4.2.4 和表 4.2）。",
